INSERT INTO meetings (id, project_id, author_id, document_no, title, meeting_date, location, purpose, content, follow_up, recording, created_at, modified_at, deleted_at) VALUES
(1, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-01-12-1', '여신 시스템 고도화 킥오프', '2026-01-12', '24F 대회의실1', '프로젝트 범위·일정·역할 분담 확정', '1. 여신본부 요구사항 정의서 리뷰\n여신본부에서 전달받은 요구사항 정의서 v1을 전체 공유했다. 핵심 개선 항목은 다음 세 가지다.\n- 심사 처리 시간 40% 단축 (현행 평균 3.2일 → 목표 1.9일)\n- 자동 심사 비중 60%까지 확대 (현행 22%)\n- 심사역 화면 UX 전면 개편\n\n2. 팀별 초기 의견\n서강우 BE팀장 - 기존 여신 심사 로직이 규칙 기반으로 얽혀 있어 자동 심사 확대가 예상보다 큰 리팩토링이 될 수 있다고 우려. 특히 예외 규정이 많은 담보대출 쪽을 걱정.\n남시우 FE파트장 - 화면 재설계 전에 여신본부 실무진 인터뷰가 필요하다는 의견. 지금 화면이 왜 불편한지 직접 들어야 제대로 된 개선이 나온다고 강조.\n문가온 QA파트장 - 자동 심사 비중이 늘어나는 만큼 리그레션 리스크가 커진다며, QA 시나리오를 프로젝트 초반부터 같이 설계하자고 제안. "개발 끝나고 테스트 붙이는 방식은 안 하겠습니다."\n윤태경 개발본부장 - 참석해 전체 방향에 동의. 다만 6월 중 여신본부 대상 중간 시연을 한 번 하고 가자고 제안 — 나중에 몰아서 피드백 받는 것보다 리스크가 적다는 이유.\n\n3. 역할 분담\n- PM실: 구본재 총괄, 정소율·하진용 선임이 스프린트 관리 지원\n- BE: 하지원 파트장 중심, 심사 로직 영향도 분석 선행\n- FE: 남시우 파트장 중심, 여신본부 인터뷰 후 화면 재설계 착수\n- QA: 문가온 파트장 중심, 초기 단계부터 시나리오 설계 병행\n\n4. 일정 영향\n6월 중간 시연이 신규 마일스톤으로 추가됨에 따라, 전체 일정을 1차/2차 스프린트로 나누는 안을 다음 회의에서 확정하기로 함.\n\n5. 리스크\n- 자동 심사 로직 리팩토링 범위가 아직 불확실 (하지원 분석 결과 대기)\n- 담보대출 예외 규정 처리 방식 미정', '하지원 - 심사 로직 영향도 분석 1/23까지. 남시우 - 여신본부 실무진 인터뷰 일정 조율. 문가온 - QA 시나리오 초안 2월 첫 주까지 작성.', NULL, '2026-01-12 09:00:00', '2026-01-12 09:00:00', NULL),
(2, 1, (SELECT id FROM users WHERE employee_no='DT22-0116'), 'MTG-2026-01-26-2', '2주차 정기 점검', '2026-01-26', '22F 포커스룸3', '초기 설계 방향 점검', '정소율 PM실 선임이 진행. 짧게 정리.\n\n진행 상황\n- 하지원 BE파트장이 심사 로직 영향도 분석 결과 공유. 자동 심사 대상 규칙 87개 중 62개는 기존 로직 재사용 가능, 나머지 25개는 신규 설계 필요.\n- 남시우 FE파트장 - 여신본부 인터뷰 결과 공유. 심사역들이 가장 불편해하는 지점은 서류 첨부 화면. "지금 화면은 첨부 파일 하나 올리는 데 5단계를 거쳐야 한다"는 실무진 코멘트를 그대로 전달.\n\n일정\n전체 일정표 초안 공유. 2월 중순 요구사항 확정을 목표로 제시. 서강우 BE팀장은 신규 설계 필요 규칙 25개 규모에 따라 일정이 밀릴 수 있다고 사전 언급.\n\n다음 회의까지\n신규 설계 규칙 25개 우선순위를 정리해서 2/9 회의에서 리뷰하기로 함.', '서강우 - 신규 설계 필요 규칙 25개 우선순위 정리. 정소율 - 확정된 일정표 전사 공유.', NULL, '2026-01-26 09:00:00', '2026-01-26 09:00:00', NULL),
(3, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-02-09-3', '요구사항 확정 전 최종 조율', '2026-02-09', '22F 포커스룸3', '남은 쟁점 정리', '여신본부 요구사항 정의서 v2 회람.\n\n확정 현황\n자동 심사 규칙 신규 설계분 25개 중 18개 확정. 나머지 7개는 리스크 기준이 모호해 재논의 필요 — 하지원 BE파트장이 각 규칙별로 어떤 지점에서 여신본부와 견해차가 있는지 하나씩 짚어줌(담보 평가 기준 3건, 소득 검증 방식 2건, 연체 이력 반영 기준 2건).\n\n성능 목표\n조민규 BE선임이 API 응답 속도 목표치를 제안 — 현행 대비 2배 개선(평균 800ms → 400ms 이하). 서강우 팀장은 "일단 목표로 잡고, 개발하면서 현실적인지 다시 보자"는 입장.\n\nQA 사전 요청\n문가온 QA파트장 - 확정 전 시나리오 리뷰를 요청. 규칙이 애매한 채로 확정되면 테스트 기준도 애매해진다는 이유.\n\n남은 쟁점 7개는 하지원이 2/13 여신본부와 재협의하기로 함.', '하지원 - 나머지 규칙 7개 여신본부와 2/13 재협의. 조민규 - API 성능 목표치 팀 내 검토 후 확정.', NULL, '2026-02-09 09:00:00', '2026-02-09 09:00:00', NULL),
(4, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-02-16-4', '요구사항 확정 보고', '2026-02-16', '24F 대회의실1', '요구사항 확정 보고', '1. 확정 결과\n여신본부와의 재협의를 거쳐 자동 심사 규칙 전체 87개 확정 완료. 남은 쟁점 7건은 전부 여신본부 안대로 반영하는 쪽으로 정리됨(리스크는 다소 보수적으로 가는 방향).\n\n2. 최종 목표 수치\n- 심사 처리 시간 40% 단축\n- 자동 심사 비중 58% (당초 60%에서 소폭 조정 — 조민규가 제안한 성능 목표와 리스크를 같이 고려해 하향)\n- API 응답 속도 400ms 이하\n\n3. 참석자 발언\n구본재 PM실장 - 확정 요구사항을 기준으로 스프린트 계획을 재수립하겠다고 밝힘. "이제부터는 숫자가 흔들리면 안 됩니다."\n남시우 FE파트장 - 서류 첨부 화면 재설계 시안 2개를 다음 회의에 제시하기로 함. B안(단계 축소형), C안(드래그앤드롭형) 두 가지로 준비 중이라고 미리 공유.\n서강우 BE팀장 - 확정 규칙 기준으로 개발 트랙을 다시 나누겠다고 언급.\n\n4. 다음 단계\n2/20까지 스프린트 계획 재수립, 3/2 1차 스프린트 착수 목표.', '구본재 - 스프린트 계획 재수립 2/20까지. 남시우 - 화면 시안 2개 준비.', NULL, '2026-02-16 09:00:00', '2026-02-16 09:00:00', NULL),
(5, 1, (SELECT id FROM users WHERE employee_no='DT22-0019'), 'MTG-2026-03-02-5', '1차 스프린트 착수 점검', '2026-03-02', '22F 포커스룸3', '스프린트 계획 확정 및 착수', '서강우 BE팀장 주관, 개발 트랙 배분 중심 논의.\n\n화면 시안 결정\n남시우 FE파트장이 제시한 B안(단계 축소형)과 C안(드래그앤드롭형) 중 B안 채택. 여신본부 인터뷰에서 나온 "단계가 너무 많다"는 코멘트를 더 직접적으로 해결한다는 이유. 정하나 FE선임을 중심으로 핵심 화면 5개 개발 배정.\n\nBE 개발 트랙 분리\n자동 심사 로직 개발을 2개 트랙으로 나눔.\n- 트랙 A(조민규 리드): 담보대출 관련 규칙 44개\n- 트랙 B(배소현 리드): 신용대출·소득 검증 관련 규칙 43개\n서강우 - "두 트랙이 겹치는 부분(연체 이력 반영)만 따로 조율 채널 만들자"고 제안.\n\n일정\n1차 스프린트 마감 4/16 목표 재확인. 문가온 QA파트장은 이 시점부터 테스트 케이스 작성 병행 시작하겠다고 보고.', '정하나 - 핵심 화면 5개 진행률 매주 공유. 조민규/배소현 - 자동 심사 로직 트랙별 진행 상황 공유.', NULL, '2026-03-02 09:00:00', '2026-03-02 09:00:00', NULL),
(6, 1, (SELECT id FROM users WHERE employee_no='DT22-0163'), 'MTG-2026-03-16-6', '개발 진행률 점검', '2026-03-16', '22F 포커스룸3', '1차 스프린트 진행률 점검', '1차 스프린트 진행률\n- 전체 진행률 92% (계획 대비)\n- 자동 심사 로직: 확정 규칙 87개 중 58개 완료, 13개 진행 중, 16개 미착수\n- 화면 개발: 핵심 화면 5개 중 4개 1차 완료\n\n이슈\n임건형 선임 담당 예외 처리 로직 지연. 담보대출 중도상환 케이스가 설계 당시 예상(7개)보다 실제로 많아(12개) 재설계 필요. 3일 지연 예상.\n\nQA 준비 상황\n문가온 파트장 - 테스트 케이스 작성 중, 4월 1주차부터 통합 테스트 가능 예상. 예외 처리 로직 미완료분은 뒤로 미뤄야 함.\n\n다음 스프린트 검토\n서강우 팀장 - 미착수 16개는 다음 스프린트로 이월, 4/16 전까지는 사전 발견 이슈 위주로 정리.', '임건형 - 예외 처리 로직 3/20까지 완료. 문가온 - 통합 테스트 환경 4/1까지 준비.', NULL, '2026-03-16 09:00:00', '2026-03-16 09:00:00', NULL),
(7, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-03-30-7', '1차 스프린트 마감 전 최종 점검', '2026-03-30', '22F 포커스룸3', '산출물 사전 검증', '1. 전체 진행 상황 점검\n1차 스프린트 마감(4/16)을 2주 앞두고 각 파트별 산출물을 최종 점검했다.\n\n2. QA 사전 발견 이슈 (문가온 QA파트장 보고)\n총 9건 발견. 화면 쪽 5건, 자동 심사 로직 쪽 4건.\n- 화면: 서류 첨부 시 파일 용량 초과 에러 메시지 미표시(critical), 심사 이력 조회 페이지네이션 오류 등 5건\n- 로직: 담보대출 중도상환 케이스 중 2건 오분류, 심사 결과 코드 매핑 오류 등 4건\n문가온 - "재현 조건은 전부 붙여놨습니다. 4/16 전까지 전량 닫는 게 목표고, 안 닫히면 완료 보고 자체를 미뤄야 한다고 봅니다."\n\n3. FE 대응 (정하나 FE선임)\n화면 이슈 5건 중 3건은 원인 파악 완료, 2건(페이지네이션 포함)은 추가 확인 필요. "페이지네이션 건은 백엔드 응답 구조랑 얽혀 있어서 조민규 선임이랑 같이 봐야 할 것 같습니다."\n\n4. BE 대응 (조민규 BE선임)\n로직 이슈 4건 중 오분류 2건은 원인 확인(예외 처리 로직 우선순위 버그), 나머지 2건은 재현 중. "페이지네이션 이슈는 저희 쪽 응답 스키마 문제 맞습니다."\n\n5. 일정 판단 (구본재 PM실장)\n9건 전량이 4/16 전에 닫힐 수 있는지가 관건. 서강우 BE팀장, 남시우 FE파트장 모두 "가능하다"는 입장이었으나, 여유를 두고 4/10을 내부 마감으로 잡자고 제안 — 완료 보고 전 재검증 시간 확보 목적.\n윤태경 개발본부장(서면 공유) - 6월 시연이 걸려 있으니 품질을 타이트하게 가져가자는 의견 전달.\n\n6. 결론\n9건 전량, 담당자별로 4/10까지 수정 완료. 4/11~15는 재검증 기간으로 확보.', '정하나/조민규 - 각 담당 이슈 4/10까지 수정 완료.', NULL, '2026-03-30 09:00:00', '2026-03-30 09:00:00', NULL),
(8, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-04-16-8', '1차 스프린트 완료 보고', '2026-04-16', '22F 포커스룸3', '1차 스프린트 산출물 점검', '1. 이슈 처리 결과\n사전 발견 이슈 9건 전량 해결 확인. QA에서 재검증 중 신규 이슈 3건 추가 발견 — 심사 결과 알림 문구 오류 1건, 첨부파일 미리보기 깨짐 1건, 담보 평가액 소수점 표기 오류 1건. 심각도는 모두 중간 이하로 백로그 등록.\n\n2. BE 진행 현황 (서강우 BE팀장)\n자동 심사 로직 커버리지 확정 규칙 87개 중 71개(82%) 개발 완료. 남은 16개는 대부분 트랙 B(신용대출) 쪽. "예상보다는 순조롭게 왔습니다. 다만 5월 중 나머지 16개를 끝내려면 인력 배분을 한번 더 봐야 할 것 같습니다."\n\n3. FE 진행 현황 (남시우 FE파트장)\n핵심 화면 5개 전체 1차 완료. 신규 이슈 2건(첨부파일 미리보기 등)은 5월 첫 주까지 처리 가능하다고 보고.\n\n4. 윤태경 개발본부장 참석 코멘트\n6월 중간 시연 일정 재확인. "1차 결과는 좋습니다. 다만 시연 때 여신본부가 실제로 써보게 할 거니까, 화면 쪽 완성도를 특히 신경 써주세요."\n\n5. 다음 단계\n2차 스프린트는 4/30 착수 예정. 신규 이슈 3건 담당자 배정 후 5월 첫 주까지 해결, 서강우는 잔여 규칙 16개를 5월 중 개발 완료하기로 함.', '신규 이슈 3건 담당자 배정 및 5월 첫 주까지 해결. 서강우 - 남은 규칙 16개 5월 중 개발 완료.', NULL, '2026-04-16 09:00:00', '2026-04-16 09:00:00', NULL),
(9, 1, (SELECT id FROM users WHERE employee_no='DT22-0163'), 'MTG-2026-04-30-9', '2차 스프린트 착수 및 시연 준비 계획', '2026-04-30', '22F 포커스룸3', '2차 스프린트 착수', '하지원 BE파트장 주관.\n\n우선순위\n자동 심사 로직 잔여 16개 규칙 개발이 2차 스프린트 최우선 과제로 배정. 하지원 - "6월 시연 전에는 무조건 87개 전량 붙어 있어야 합니다. 트랙 B 인력을 좀 더 붙이겠습니다."\n\n시연 준비\n남시우 FE파트장 - 6월 시연에서 보여줄 화면 시나리오 초안 공유. 여신 접수→자동 심사→결과 확인까지 엔드투엔드로 보여주는 구성.\n정소율 PM실 선임 - 시연 리허설을 6월 첫 주로 제안. 실제 시연 하루 전에 한 번 더 리허설하는 안도 같이 제시.\n\n일정\n잔여 규칙 16개 5/28까지 개발 완료 목표. 리허설 일정은 여신본부와 별도 조율.', '서강우 - 잔여 규칙 16개 5/28까지 개발 완료. 정소율 - 리허설 일정 여신본부와 조율.', NULL, '2026-04-30 09:00:00', '2026-04-30 09:00:00', NULL),
(10, 1, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2026-05-14-10', '시연 준비 중간 점검', '2026-05-14', '22F 포커스룸3', '시연 시나리오 리뷰', '남시우 FE파트장 주관, 화면 흐름 중심.\n\n시나리오 리뷰\n남시우가 준비한 화면 흐름을 문가온 QA파트장이 실사용자 관점에서 리뷰. 부자연스러운 구간 3곳 지적.\n1) 여신 접수 화면에서 필수 입력값 안내가 너무 늦게 뜬다\n2) 자동 심사 결과 화면에서 "왜 이 결과가 나왔는지"에 대한 설명이 없다\n3) 서류 첨부 완료 후 다음 단계로 넘어가는 버튼 위치가 헷갈린다\n남시우 - "1, 3번은 바로 고칠 수 있는데, 2번은 여신본부가 원하는 설명 수준을 다시 물어봐야 할 것 같습니다."\n\nBE 진행 상황\n서강우 BE팀장 - 자동 심사 로직 개발이 계획보다 하루 앞서 진행 중이라고 보고. 트랙 B 인력 추가 투입이 효과가 있었다고 언급.\n\n다음 단계\n지적된 3개 구간 화면 흐름 수정, 리허설 참석자 명단(여신본부 포함) 확정.', '남시우 - 지적된 3개 구간 화면 흐름 수정. 정소율 - 리허설 참석자(여신본부 포함) 명단 확정.', NULL, '2026-05-14 09:00:00', '2026-05-14 09:00:00', NULL),
(11, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-05-28-11', '시연 리허설', '2026-05-28', '23F 고객 응접실', '본 시연 전 최종 리허설', '1. 리허설 결과\n실제 시연 환경에서 리허설 진행. 자동 심사 로직 87개 규칙 전체 정상 동작 확인.\n\n2. 발견된 문제\n심사 건수가 많을 때(동시 30건 이상) 응답 지연 발생. 조민규 BE선임 - 원인은 DB 쿼리 최적화 부족으로 추정. "인덱스를 다시 봐야 할 것 같은데, 지금 붙어서 보면 6/8까지는 끝낼 수 있습니다."\n\n3. 참석자 반응\n남시우 FE파트장 - 화면 흐름 자체는 이전 지적사항 반영돼 자연스러워졌다고 평가.\n문가온 QA파트장 - 응답 지연 외에는 기능적 이슈 없음. 다만 지연 문제는 본 시연에서 재현될 경우 치명적이라고 경고.\n\n4. PM 판단 (구본재)\n"6/11 본 시연까지 시간이 촉박합니다. 쿼리 최적화를 최우선으로 두고, 혹시 안 끝나면 시연 당일 데이터 규모를 조절하는 백업 시나리오도 준비해주세요." 우선순위 조정을 팀 전체에 요청.', '조민규 - 쿼리 최적화 6/8까지 완료. 구본재 - 시연 당일 백업 시나리오 준비.', NULL, '2026-05-28 09:00:00', '2026-05-28 09:00:00', NULL),
(12, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-06-11-12', '중간 시연 결과 논의', '2026-06-11', '23F 고객 응접실', '여신본부 대상 중간 시연 피드백 정리', '1. 시연 개요\n여신본부 대상 중간 시연 진행. 윤태경 개발본부장 배석.\n\n2. 잘된 점\n자동 심사 처리 속도는 목표치(400ms 이하) 충족 확인. 조민규 선임의 쿼리 최적화가 시연 전날 마무리돼 지연 문제 없이 진행.\n\n3. 문제가 된 지점\n여신본부 실무진으로부터 화면 UX에 대한 부정적 피드백이 다수 제기됨. 핵심은 클릭 단계가 기존 대비 오히려 늘었다는 지적.\n- 서류 첨부 화면: 파일 종류별로 별도 업로드 버튼이 생기면서 클릭 수 증가\n- 심사 결과 확인 화면: 상세 내역을 보려면 팝업을 3번 거쳐야 함\n여신본부 실무진 코멘트(구본재 전달) - "빨라진 건 알겠는데, 이거 저희가 쓰는 화면이거든요. 저희 입장에서 다시 봐주셨으면 합니다."\n\n4. 결정\n윤태경 개발본부장이 배석한 자리에서 UI 전면 재작업 결정. "숫자는 통과했으니 이제 사람이 쓰기 편한지가 남았습니다. 다시 갑시다."\n남시우 FE파트장 - 재작업 범위를 이번 주 내로 산정하겠다고 밝힘.\n\n5. 후속 대응\n구본재 - 여신본부에 재작업 일정을 공유하고 시연을 연기하겠다고 안내하기로 함. 원래 예정된 정식 오픈 일정에는 영향 없음을 재확인.', '남시우 - 재작업 범위·일정 6/18까지 확정. 구본재 - 여신본부에 재작업 일정 공유 및 시연 연기 안내.', NULL, '2026-06-11 09:00:00', '2026-06-11 09:00:00', NULL),
(13, 1, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2026-06-25-13', 'UI 재작업 범위 확정 및 착수', '2026-06-25', '22F 포커스룸3', '재작업 범위 확정', '남시우 FE파트장 주관.\n\n재작업 범위\n총 8개 화면이 재설계 대상으로 확정.\n- 서류 첨부 화면(파일 종류 통합 업로드로 변경)\n- 심사 결과 확인 화면(팝업 3단계→1단계로 축소)\n- 그 외 접수 현황, 심사 이력 조회 등 연관 화면 6개\n\n인력 배치\n남시우 - 파트원 전원을 재작업에 투입, 다른 신규 개발은 일시 중단. "이번엔 여신본부 실무진 검토를 중간에 한 번 더 넣겠습니다." 정하나 FE선임이 재작업 총괄.\n\n일정\n8개 화면 재설계 완료 목표는 7/21. 중간에 여신본부 실무진 검토를 7/9경 진행하기로 잠정 합의.', '정하나 - 8개 화면 재작업 진행률 격주 공유. 남시우 - 여신본부 실무진 중간 검토 일정 조율.', NULL, '2026-06-25 09:00:00', '2026-06-25 09:00:00', NULL),
(14, 1, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2026-07-09-14', 'UI 재작업 중간 점검', '2026-07-09', '22F 포커스룸3', '재작업 진행률 및 실무진 중간 검토', '정하나 FE선임 진행 상황 보고 + 여신본부 실무진 3명 초청 검토.\n\n진행률\n8개 대상 화면 중 5개 재설계 완료(서류 첨부, 심사 결과 확인 포함).\n\n실무진 검토 결과\n전반적으로 긍정적 반응. "첨부 화면은 확실히 나아졌다"는 코멘트. 다만 심사 결과 확인 화면에서 정보 밀도가 너무 낮다는 의견 — 팝업 단계는 줄었지만 화면당 정보가 부족해 오히려 여러 화면을 오가야 한다는 지적.\n\n대응 방향\n정하나 - 정보 밀도와 클릭 단계 사이 균형을 다시 잡겠다고 답변. "1단계로 줄인 게 능사는 아니었나 봅니다."', '정하나 - 심사 결과 확인 화면 재조정 7/16까지. 문가온 - 재설계 화면 QA 병행 착수.', NULL, '2026-07-09 09:00:00', '2026-07-09 09:00:00', NULL),
(15, 1, (SELECT id FROM users WHERE employee_no='DT22-0127'), 'MTG-2026-07-21-15', 'UI 재작업 완료 점검', '2026-07-21', '22F 포커스룸3', '재작업 결과 검증', '문가온 QA파트장 진행, 회귀 테스트 결과 중심.\n\n1. 재설계 완료 확인\n재작업 대상 8개 화면 전체 완료. 심사 결과 확인 화면은 정보 밀도를 조정해 팝업 2단계(1단계에서 소폭 조정)로 최종 정리.\n\n2. 회귀 테스트 결과\n문가온 - "회귀 테스트 전체 돌렸고, 신규 이슈는 없습니다. 재작업 전 기능들이 깨진 것도 없고요." 테스트 케이스 총 64건 전량 통과.\n\n3. 다음 단계\n구본재 PM실장 - 여신본부에 재확인 데모 일정 제안, 8월 첫 주로 잠정 합의.\n윤태경 개발본부장 - 이번 재작업 경험을 언급하며, 향후 대형 프로젝트에서는 중간 시연을 더 이른 시점에 배치하자고 제안. "한 번 더 겪었으면 하는 일은 아니었지만, 배운 건 있네요."', '구본재 - 여신본부 재확인 데모 일정 최종 확정. 서강우 - 2차 스프린트 재개 계획 수립.', NULL, '2026-07-21 09:00:00', '2026-07-21 09:00:00', NULL),
(16, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-08-04-16', '2차 스프린트 재개 및 병목 점검', '2026-08-04', '22F 포커스룸3', '진행률 점검 및 리스크 조기 파악', '1. 재개 배경\n재작업으로 중단됐던 2차 스프린트를 재개. 하지원·남시우·문가온 세 파트장이 각자 파트의 병목 구간을 공유.\n\n2. BE 병목 (하지원)\n잔여 자동 심사 규칙 16개 중 9개가 아직 미개발 상태. 재작업 대응 인력 재배치로 진행이 밀림.\n\n3. FE 병목 (남시우)\n재작업 여파로 신규 화면 개발이 계획보다 3주 밀린 상태. "재작업이 끝났다고 바로 정상 속도가 나오진 않네요, 파트원들이 좀 지쳐 있습니다."\n\n4. QA 상황 (문가온)\n재작업 화면은 검증 완료됐고, 2차 스프린트 신규 개발분 QA는 아직 여유 있음.\n\n5. 구본재 PM실장 판단\n"BE 쪽 잔여 9개가 제일 리스크가 큽니다." 백엔드 인력 2명 추가 투입을 검토하겠다고 밝힘. 다만 어느 파트에서 인력을 빼올지는 서강우 팀장과 별도 협의 필요.', '구본재 - 인력 추가 투입 여부 8/10까지 결정. 하지원 - 잔여 규칙 9개 우선순위 재정렬.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(17, 2, (SELECT id FROM users WHERE employee_no='DT22-0118'), 'MTG-2026-03-05-17', '해외주식 주문개선 킥오프', '2026-03-05', '22F 포커스룸1', '문제 정의 및 목표 합의', '1. 문제 현황 공유\n다온증권 해외주식 주문 관련 고객 불만 데이터를 리뷰했다.\n- 주문 처리 지연: 평균 4.2초 (내부 목표 1.5초 이하)\n- 환율 표시 오차 신고: 월 30건\n- 원인은 크게 두 갈래 — 주문 처리 로직 자체 지연, 환율 정보 연동 방식(배치성 갱신) 문제\n\n2. 파트별 초기 의견\n하유진 BE파트장 - "지금 주문 처리가 동기 호출 체인으로 얽혀 있어서, 환율 조회 하나가 늦어지면 전체가 늦어지는 구조입니다. 환율 연동을 먼저 뜯어봐야 할 것 같습니다."\n오하린 FE파트장 - 화면 쪽도 손볼 필요가 있다는 의견. "환율 오차 신고 중 절반은 실제 오차가 아니라 화면에 표시되는 갱신 시점이 안 보여서 생기는 오해입니다. 갱신 시각 표기만 넣어도 신고가 줄 것 같습니다."\n정미르 QA팀장 - 회귀 리스크를 우려. 주문 처리 로직을 건드리는 만큼 QA 범위를 넓게 잡아야 한다고 제안.\n\n3. 목표 설정\n- 주문 처리 시간 1.5초 이하\n- 환율 오차 신고 월 5건 이하\n\n4. 역할 분담\n곽태희 PM선임 총괄, BE는 하유진 파트장 중심(임동혁·조현아·배승우 선임), FE는 오하린 파트장 중심(임도경·표서연 선임), QA는 정미르 팀장 산하 정라온·문가율.\n\n5. 다음 단계\n하유진 - 현행 API 응답시간 실측을 3/12까지 완료, 이를 기준으로 개선 목표 재검토.', '하유진 - 현행 API 응답시간 측정 3/12까지.', NULL, '2026-03-05 09:00:00', '2026-03-05 09:00:00', NULL),
(18, 2, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2026-03-19-18', '설계 방향 점검', '2026-03-19', '22F 포커스룸1', '환율 연동 아키텍처 검토', '임동혁 BE선임 발표.\n\n외부 환율 API 비교\n3개 업체(A사·B사·C사)를 응답속도·안정성·비용 기준으로 비교했다.\n- A사: 평균 120ms, 안정성 99.95%, 비용 중간\n- B사: 평균 200ms, 안정성 99.9%, 비용 최저\n- C사: 평균 90ms, 안정성 99.8%, 비용 최고\n\n임동혁 - "속도는 C사가 제일 좋은데 안정성이 살짝 아쉽고, 비용까지 고려하면 A사가 균형이 낫다고 봅니다."\n\n결정\nA사로 잠정 선정, 다만 실측 PoC를 거쳐 최종 확정하기로 함.\n\n하유진 BE파트장 - 현행 API 응답시간 측정 결과 공유(평균 4.2초 중 환율 조회 대기가 2.8초 차지). "역시 환율 쪽이 병목의 대부분이었네요. PoC 결과가 좋으면 개선 목표는 충분히 달성 가능해 보입니다."', '임동혁 - A사 연동 PoC 4/2까지.', NULL, '2026-03-19 09:00:00', '2026-03-19 09:00:00', NULL),
(19, 2, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'MTG-2026-04-02-19', 'PoC 결과 점검', '2026-04-02', '22F 포커스룸1', '연동 PoC 검증', 'A사 환율 API PoC 결과, 평균 응답 120ms로 목표(200ms)를 상회 달성. 임동혁 - "안정성도 2주 관찰 기간 동안 이슈 없었습니다. A사로 확정하시죠."\n\n표서연 FE선임이 주문 플로우 화면 재설계안 제시. 환율 갱신 시각을 화면에 명시하고, 오차 신고가 잦았던 항목(호가 표시)에 툴팁 설명을 추가하는 안. 오하린 FE파트장도 동의.\n\n정미르 QA팀장 - "화면안은 좋은데, 시안 확정되면 QA 시나리오 검토 먼저 받고 개발 들어가주세요. 리소스 이중 투입 막고 싶어서요."', '표서연 - 화면안 QA 검토 요청.', NULL, '2026-04-02 09:00:00', '2026-04-02 09:00:00', NULL),
(20, 2, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2026-04-16-20', '1차 개발 착수 점검', '2026-04-16', '22F 포커스룸1', '개발 진행률 점검', '하유진 BE파트장 진행.\n\n주문 처리 로직 개발 진행률 40%. A사 환율 API 연동은 완료, 기존 동기 호출 체인을 비동기로 전환하는 작업이 진행 중.\n\n이슈\n조현아 BE선임 담당 로직에서 동시성 이슈 1건 발견 — 동시에 여러 주문이 들어올 때 환율 캐시 갱신 타이밍이 꼬이는 문제. 임시로 락을 걸어 조치했으나 근본 해결은 아님. 조현아 - "지금 락 방식은 트래픽 몰릴 때 오히려 병목이 될 수 있어서, 구조를 좀 더 봐야 합니다."\n\n표서연 FE선임 - 화면 재설계 진행률 30%, QA 시나리오 검토 반영해 재작업 중.', '조현아 - 동시성 이슈 근본 수정 4/30까지.', NULL, '2026-04-16 09:00:00', '2026-04-16 09:00:00', NULL),
(21, 2, (SELECT id FROM users WHERE employee_no='DT22-0020'), 'MTG-2026-04-30-21', '1차 개발 완료 점검', '2026-04-30', '22F 포커스룸1', '개발 완료 확인', '1. 개발 완료 확인\n조현아 BE선임이 동시성 이슈 근본 수정 완료를 보고. 락 방식 대신 환율 캐시를 사용자별이 아닌 통화쌍별로 분리해 충돌 자체를 없애는 구조로 변경. "부하 테스트에서도 문제없었습니다."\n\n2. 전체 진행률\n하유진 BE파트장 - 주문 처리 로직, 화면 재설계 모두 1차 개발 완료.\n\n3. QA 준비\n정미르 QA팀장이 QA 착수 일정을 5월 첫 주로 확정. "회귀 리스크가 있는 프로젝트라 QA 기간은 넉넉하게 잡겠습니다."\n\n4. 다음 단계\n정라온 QA선임이 QA 시나리오 최종본을 5/8까지 공유하기로 함.', '정라온 - QA 시나리오 최종본 5/8 공유.', NULL, '2026-04-30 09:00:00', '2026-04-30 09:00:00', NULL),
(22, 2, (SELECT id FROM users WHERE employee_no='DT22-0136'), 'MTG-2026-05-14-22', 'QA 착수 점검', '2026-05-14', '22F 포커스룸1', 'QA 진행 준비 확인', '실환경 연동 테스트 계획 수립. 임동혁 BE선임이 다음 주부터 A사 API 실환경 연동에 착수한다고 보고.\n\n정라온 QA선임 - 시나리오 최종본 공유 완료, 총 42개 케이스로 구성. 주문 처리 24건, 환율 표시 12건, 예외 케이스 6건.\n\n하유진 BE파트장 - 실환경 연동 시점에 트래픽이 몰리지 않는 새벽 시간대로 잡아달라고 요청.', '임동혁 - 연동 착수.', NULL, '2026-05-14 09:00:00', '2026-05-14 09:00:00', NULL),
(23, 2, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'MTG-2026-05-28-23', '환율 API 이슈 발생 대응', '2026-05-28', '22F 포커스룸1', '연동 지연 원인 파악', '5/29 예정이던 실환경 연동이 A사 API 응답 지연으로 차질을 빚었다.\n\n증상\n건당 3~5초까지 응답이 늘어짐(PoC 당시 120ms 대비 대폭 저하). 임동혁 BE선임 - "PoC 때와 환경이 다른 게 유일한 차이인데, 원인을 아직 못 찾았습니다. A사 쪽에 문의 넣었습니다."\n\n최윤성 DevOps팀장(서면 공유) - 네트워크 구간 자체는 이상 없음을 확인해줬다는 내용 전달.\n\n대응\n임동혁이 A사에 장애 문의를 넣었고, 지수민 DevOps선임과 공동으로 원인을 분석하기로 함. 하유진 - "일단 오픈 일정에 영향 없는 선에서 원인 파악 기간을 확보하겠습니다."', '임동혁 - A사에 장애 문의, 최윤성 DevOps팀장과 공동 분석.', NULL, '2026-05-28 09:00:00', '2026-05-28 09:00:00', NULL),
(24, 2, (SELECT id FROM users WHERE employee_no='DT22-0055'), 'MTG-2026-06-11-24', '환율 API 이슈 재점검', '2026-06-11', '22F 포커스룸1', '대응 방안 확정', '지연이 2주째 지속되는 것을 확인했다. A사 측 답변은 "내부 트래픽 급증으로 인한 일시적 저하"였으나 개선 시점은 불명확.\n\n지수민 DevOps선임이 캐싱 레이어 도입을 우회 방안으로 제안. "환율이 밀리초 단위로 바뀌는 게 아니니까, 짧은 TTL(예: 5초)로 캐싱하면 A사 응답 지연의 영향을 거의 안 받을 것 같습니다."\n\n하유진 BE파트장 - 캐싱 방향에 동의하되, A사와 별도로 SLA 재협의도 병행하자고 제안. "우회는 임시방편이니, 계약상 응답속도 보장도 다시 짚고 넘어가야죠."', '지수민 - 캐싱 PoC 6/25까지, 하유진 - A사와 SLA 재협의.', NULL, '2026-06-11 09:00:00', '2026-06-11 09:00:00', NULL),
(25, 2, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'MTG-2026-06-25-25', '복구 방안 확정', '2026-06-25', '22F 포커스룸1', '캐싱 레이어 적용 결정', '지수민 DevOps선임의 캐싱 레이어 PoC 결과 공유. TTL 5초 캐싱 적용 시 평균 응답 150ms로 A사 지연과 무관하게 안정적 성능 확인.\n\n결정: 캐싱 레이어 정식 적용.\n\n일정 영향\n이번 이슈로 약 2주 지연이 확정됨에 따라 QA 일정을 재조정. 정미르 QA팀장 - "지연은 아쉽지만 캐싱 구조 자체는 장기적으로도 안정성에 도움이 될 것 같아서 나쁘지 않은 선택이라고 봅니다."\n\n하유진 - A사와의 SLA 재협의는 계속 진행 중이며 별도로 보고하기로 함.', '임동혁 - 정식 적용 7/9까지.', NULL, '2026-06-25 09:00:00', '2026-06-25 09:00:00', NULL),
(26, 2, (SELECT id FROM users WHERE employee_no='DT22-0136'), 'MTG-2026-07-09-26', '환율 API 복구 확인', '2026-07-09', '22F 포커스룸1', '복구 결과 검증 및 QA 재개', '캐싱 레이어 정식 적용 완료, 환율 연동 응답속도 정상 확인(평균 140ms).\n\nQA 재개\n문가율 QA사원이 기본 테스트 케이스 20건 재실행 완료를 보고. 이슈 기간 동안 중단됐던 QA를 재개.\n\n정라온 QA선임 - 남은 22개 케이스에 대해서도 회귀 테스트 전체를 다시 돌리겠다고 밝힘. "중간에 구조가 바뀐 부분(캐싱)이 있어서 이미 통과했던 케이스도 다시 봐야 할 것 같아요."', '정라온 - 회귀 테스트 전체 재실행.', NULL, '2026-07-09 09:00:00', '2026-07-09 09:00:00', NULL),
(27, 2, (SELECT id FROM users WHERE employee_no='DT22-0128'), 'MTG-2026-07-23-27', 'QA 진행 점검', '2026-07-23', '22F 포커스룸1', 'QA 진행률 확인', '하승우 QA파트장 주관.\n\nQA 진행률 65%(42건 중 27건 완료). 발견 이슈 8건 중 6건 수정 완료.\n\n잔여 이슈\n강나은 FE사원 담당 기초 화면(환율 갱신 시각 표기)에 잔여 버그 2건. 특정 브라우저에서 시각 표기가 깨지는 문제. 강나은 - "재현은 됐는데 원인이 CSS 쪽인지 다른 쪽인지 좀 더 봐야 할 것 같습니다."\n\n하유진 BE파트장 - 나머지 15건 QA는 8월 첫 주까지 완료 가능할 것으로 예상.', '강나은 - 잔여 버그 8/1까지.', NULL, '2026-07-23 09:00:00', '2026-07-23 09:00:00', NULL),
(28, 2, (SELECT id FROM users WHERE employee_no='DT22-0118'), 'MTG-2026-08-04-28', 'QA 최종 점검 회의', '2026-08-04', '22F 포커스룸1', '오픈 전 최종 이슈 정리', '1. 이슈 처리 결과\n잔여 이슈 8건 전량 해결 확인. 강나은 사원이 보고한 브라우저별 표기 버그도 CSS 우선순위 문제로 확인되어 수정 완료.\n\n2. 전체 QA 결과\n정라온 QA선임 - 총 42개 케이스 전량 통과, 회귀 테스트 포함 이슈 재발 없음.\n\n3. 성능 재확인\n하유진 BE파트장 - 주문 처리 시간 목표(1.5초 이하) 대비 평균 1.2초로 목표 달성. 환율 오차 신고 관련 화면 개선도 반영 완료.\n\n4. 오픈 계획\n곽태희 PM선임 - 오픈 전 최종 리뷰 일정을 8월 중순으로 제안. "이슈 이력 때문에 일정이 좀 밀리긴 했지만, 결과적으로는 더 안정적인 구조로 나온 것 같습니다."', '하유진 - 오픈 체크리스트 작성.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(29, 3, (SELECT id FROM users WHERE employee_no='DT22-0198'), 'MTG-2026-05-11-29', '정산 배치 재구축 킥오프', '2026-05-11', '21F 포커스룸', '정산 배치 장애 원인 공유 및 재구축 범위 합의', '1. 배경 공유\n2025년 발생한 정산 배치 장애(야간 배치 중 일부 거래 정산 누락, 익일 오전 수기 정정)의 재발 방지 요건을 정리했다. 조태현 BE파트장이 당시 장애 타임라인을 재구성해 공유.\n- 원인: 배치 잡 간 의존관계가 코드에만 존재하고 문서화되지 않아, 순서 변경 시 영향 파악 실패\n- 재발 방지 요건: 전체 배치 잡 의존관계 문서화, 실패 시 자동 재시도/알림 체계 구축, 정산 결과 자동 검증 로직 추가\n\n2. 팀 의견\n서강우 BE팀장 - "일단 지금 뭐가 있는지부터 다 파악해야 합니다. 새로 짜는 것보다 먼저 현행을 정확히 아는 게 우선이에요."\n강지호 QA선임 - 정산 데이터는 금액이 걸린 영역이라 검증 기준을 처음부터 타이트하게 잡자고 제안.\n\n3. 진행 방식\n1단계 레거시 전수 분석 → 2단계 신규 로직 설계 → 3단계 개발/검증 순으로 진행하기로 함. 임서진 PM선임이 전체 일정 관리.\n\n4. 역할\n최재원 BE선임 - 레거시 배치 코드 전수 조사 담당. 임소현 BE선임 - 분석 결과를 바탕으로 신규 설계 병행 검토.', '최재원 - 레거시 분석 착수.', NULL, '2026-05-11 09:00:00', '2026-05-11 09:00:00', NULL),
(30, 3, (SELECT id FROM users WHERE employee_no='DT22-0200'), 'MTG-2026-06-01-30', '레거시 분석 착수 점검', '2026-06-01', '21F 포커스룸', '분석 범위 확정', '최재원 BE선임 보고.\n\n전수 조사 결과, 총 배치 잡 47개 중 문서화된 것은 12개뿐. 나머지 35개는 코드를 직접 읽어야만 로직을 파악할 수 있는 상태.\n\n최재원 - "예상보다 훨씬 심각합니다. 담당자가 바뀐 잡들은 왜 이렇게 짜여 있는지 이유를 아는 사람이 아무도 없어요. 하나씩 실행해보면서 역추적해야 할 것 같습니다."\n\n임소현 BE선임 - 문서화된 12개를 기준으로 신규 로직 설계를 병행 착수하겠다고 제안. "나머지 분석을 다 기다리면 일정이 너무 밀리니까, 확실한 것부터 먼저 설계 시작하겠습니다."\n\n조태현 BE파트장 - 두 작업을 병행하되 주 1회 이상 교차 점검하자고 제안.', '최재원 - 나머지 35개 잡 분석 6/22까지.', NULL, '2026-06-01 09:00:00', '2026-06-01 09:00:00', NULL),
(31, 3, (SELECT id FROM users WHERE employee_no='DT22-0200'), 'MTG-2026-06-22-31', '레거시 분석 중간 점검', '2026-06-22', '21F 포커스룸', '진행률 확인', '1. 진행률\n47개 배치 잡 중 30개 분석 완료(64%). 최재원 BE선임 - "속도는 나쁘지 않은데, 문제는 남은 것 중 8개입니다."\n\n2. 강결합 배치 8개\n다른 시스템(대외계, 회계)과 강하게 결합돼 있어 재구축 난도가 특히 높은 8개 배치 잡 확인. 단순 리팩토링이 아니라 인터페이스 자체를 다시 설계해야 할 가능성이 있음.\n\n3. QA 계획\n강지호 QA선임이 검증 계획 초안 공유. 정산 금액 검증은 이중 계산(신규 로직 결과와 레거시 결과를 병행 실행해 비교) 방식을 제안. "숫자가 걸린 거라 사람이 눈으로 보는 것보다 시스템으로 비교하는 게 안전합니다."\n\n4. 리스크\n조태현 BE파트장 - 강결합 8개가 전체 일정의 핵심 변수가 될 것으로 예상, 다음 회의에서 별도 대응 방안 논의 필요.', '최재원 - 강결합 배치 8개 별도 대응 방안 7/13까지.', NULL, '2026-06-22 09:00:00', '2026-06-22 09:00:00', NULL),
(32, 3, (SELECT id FROM users WHERE employee_no='DT22-0198'), 'MTG-2026-07-13-32', '레거시 분석 지연 대응', '2026-07-13', '21F 포커스룸', '일정 지연 대응 방안 논의', '강결합 배치 8개 분석 결과 공유. 예상보다 재구축 난도가 높아 분석 자체가 2주 추가 지연됐다.\n\n원인\n최재원 BE선임 - "8개 중 5개는 대외계 시스템 응답 형식에 맞춰 임시방편으로 짜여 있었습니다. 그대로 옮기면 같은 문제가 재발할 수 있어서, 인터페이스 설계부터 다시 봐야 합니다."\n\n조태현 BE파트장 판단\n전체 일정 재수립이 필요하다고 판단, 서강우 BE팀장에게 보고. 서강우 - "정산은 잘못되면 신뢰 문제로 바로 이어지니까, 서두르다 놓치는 것보다는 낫습니다. 남기훈 부사장님께는 제가 직접 보고하겠습니다."\n\n다음 단계\n조태현이 현실적인 신규 일정안을 작성하기로 함.', '서강우 - 남기훈 부사장 보고, 조태현 - 신규 일정안 작성.', NULL, '2026-07-13 09:00:00', '2026-07-13 09:00:00', NULL),
(33, 3, (SELECT id FROM users WHERE employee_no='DT22-0201'), 'MTG-2026-08-04-33', '레거시 분석 마무리 및 설계 착수 점검', '2026-08-04', '21F 포커스룸', '분석 완료 확인 및 설계 착수', '1. 분석 완료\n47개 배치 잡 전량 분석 완료. 강결합 8개를 포함해 전체 의존관계 문서화 완료. 최재원 - "이제 뭐가 뭘 건드리는지는 확실히 알게 됐습니다. 예상보다 6주 더 걸렸지만, 다음 단계부터는 헤매지 않을 것 같습니다."\n\n2. 설계 진행\n임소현 BE선임 - 신규 로직 설계 20% 진행. 문서화된 12개 기준으로 먼저 설계했던 부분은 순조로우나, 강결합 8개는 이제 설계 시작 단계.\n\n3. 재발 방지 요건 충족 여부\n조태현 BE파트장 - 애초 목표였던 의존관계 문서화는 100% 달성 확인. 자동 재시도/알림 체계, 자동 검증 로직은 설계 단계에서 반영 예정.\n\n4. 일정 재설정\n임서진 PM선임 - 지연을 반영해 설계 완료 목표를 9월 말로 재설정. "1단계가 예상보다 오래 걸린 만큼, 2단계는 좀 더 보수적으로 잡겠습니다."', '임소현 - 설계 완료 목표를 9월 말로 재설정.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(34, 4, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2026-06-08-34', '한빛저축은행 컨설팅 킥오프', '2026-06-08', '고객사(한빛저축은행 본사)', '진단 범위 및 일정 합의', '1. 고객사 현황 청취\n한빛저축은행 측(IT기획팀장, 경영지원본부장 등 4명 참석)으로부터 현행 코어뱅킹 시스템 현황과 애로사항을 청취했다. 핵심 요청은 "차세대 전환까지는 아니어도, 지금 시스템으로 얼마나 더 버틸 수 있는지, 어디부터 손봐야 하는지 진단해달라"는 것.\n\n2. 안세희 팀장 코멘트\n"차세대 전환 컨설팅이 아니라 노후도 진단과 우선순위 제시가 목적입니다. 고객사도 예산이 정해져 있는 상황이라 실행 가능한 수준의 제안이 중요합니다."\n\n3. 진단 범위 합의\n- 코어뱅킹 모듈별 노후도 평가(여신·수신·외환)\n- 데이터 이관 리스크 평가\n- 우선순위별 개선 로드맵 제시\n\n4. 산출물 목록 확정\n중간 보고서(현황 진단), 최종 보고서(로드맵 포함) 2단계로 확정.\n\n5. 역할 분담\n석다연 파트장 - 진단 총괄. 권도영·홍재현·임세아·노태섭·공서희 선임 - 현장 인터뷰 및 자료 분석 분담.', '현장 인터뷰 일정 수립.', NULL, '2026-06-08 09:00:00', '2026-06-08 09:00:00', NULL),
(35, 4, (SELECT id FROM users WHERE employee_no='DT22-0095'), 'MTG-2026-06-29-35', '현장 인터뷰 진행 점검', '2026-06-29', '고객사(한빛저축은행 본사)', '인터뷰 진행 상황 공유', '권도영 컨설팅선임 - 여신·수신 부서 실무진 8명 인터뷰 완료 보고. "다들 시스템 자체보다는 야간 배치 시간이 계속 늘어나는 걸 제일 불안해하시더라고요. 지금 4시간 걸리는데 2년 전엔 2시간이었답니다."\n\n홍재현 컨설팅선임 - 데이터 이관 관련 레거시 문서가 부실하다고 지적. "이관 이력 문서가 있는 부분도 있고 없는 부분도 있어서, 있는 것만 보고 판단하면 안 될 것 같습니다. 데이터 쪽은 별도로 실사를 한번 들어가야 할 것 같아요."\n\n석다연 파트장 - 실사 필요성에 동의, 다음 주 일정 조율 지시.', '홍재현 - 데이터 실사 일정 7/6까지 협의.', NULL, '2026-06-29 09:00:00', '2026-06-29 09:00:00', NULL),
(36, 4, (SELECT id FROM users WHERE employee_no='DT22-0092'), 'MTG-2026-07-20-36', '진단 결과 초안 리뷰', '2026-07-20', '21F 대회의실', '내부 진단 결과 사전 검토', '석다연 파트장 발표.\n\n1. 진단 결과\n현행 코어뱅킹 시스템 진단 초안 공유. 노후 모듈 3개(여신 심사 엔진, 배치 스케줄러, 외환 정산 모듈)가 교체 필요 등급(가장 낮은 등급)으로 분류됨. "이 셋은 유지보수만으로는 한계가 있어 보입니다. 나머지는 개선 등급 정도로 충분해요."\n\n2. 데이터 실사 결과\n홍재현 컨설팅선임 - 실사 결과 이관 이력 미문서화 구간이 전체 데이터의 약 15%로 확인. 리스크로 별도 기재하기로 함.\n\n3. 산출물 구성\n임세아 컨설팅선임이 최종 보고서 목차를 확정. 현황 진단 → 리스크 평가 → 우선순위별 로드맵(단기/중기/장기) 순서로 구성.\n\n4. 다음 단계\n공서희 컨설팅선임이 보고서 초안 작성을 맡아 8/3까지 완성하기로 함.', '공서희 - 보고서 초안 8/3까지 작성.', NULL, '2026-07-20 09:00:00', '2026-07-20 09:00:00', NULL),
(37, 4, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2026-08-03-37', '1차 산출물 최종 점검', '2026-08-03', '21F 대회의실', '고객 보고 전 최종 점검', '1. 초안 완성\n공서희 컨설팅선임이 진단 보고서 초안 완성을 보고. "노후 모듈 3개는 왜 교체가 필요한지 근거 데이터를 최대한 붙였습니다. 특히 배치 스케줄러는 처리 시간 추이 그래프로 보여드리는 게 설득력 있을 것 같았어요."\n\n2. 내용 검토\n안세희 팀장이 보고서 전반을 검토, 우선순위 로드맵 부분에서 고객사 예산 규모를 감안해 단기 항목을 좀 더 구체적으로(견적 수준까지) 다듬어달라고 요청.\n\n3. 영업 관점 (함지수 파트장)\n"이 정도 진단이면 이후 구축 사업으로 이어질 가능성이 꽤 있어 보입니다. 로드맵 발표할 때 그 부분도 자연스럽게 짚어주시죠." 다만 이번 산출물 자체는 진단에 충실하게 마무리하자는 데 의견 일치.\n\n4. 다음 단계\n안세희 - 고객사 중간 보고 일정을 다음 주로 확정, 최종 보고 자료 검토 직접 진행하기로 함.', '안세희 - 고객사 보고 자료 최종 검토.', NULL, '2026-08-03 09:00:00', '2026-08-03 09:00:00', NULL),
(38, 5, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'MTG-2026-02-10-38', '서일캐피탈 착수 회의', '2026-02-10', '고객사(서일캐피탈 본사)', '계약 범위 재확인 및 착수 보고', '1. 계약 범위 재확인\n서일캐피탈 여신심사 시스템 구축 계약 범위를 고객사와 재확인했다. 여신심사 프로세스 전체를 시스템화하되, 기존 코어뱅킹 연동은 유지하는 것으로 최종 합의.\n\n2. 구본재 PM실 팀장 코멘트\n"이번 건은 컨설팅팀과 PM실이 공동으로 들어갑니다. 컨설팅팀이 프로세스 분석과 현장 대응을 맡고, 저희 쪽은 개발 착수 이후 일정 관리를 맡는 구조로 가겠습니다."\n\n3. 역할 분담\n편도현 컨설팅파트장 - 여신심사 프로세스 분석 총괄. 최한결 PM선임 - 현장 상주 인력 배치 및 커뮤니케이션 채널 관리.\n\n4. 고객사 요청사항\n서일캐피탈 측에서 기존 심사역들의 업무 방식을 최대한 유지하는 선에서 시스템화해달라는 요청. "업무가 바뀌는 게 아니라 도구가 바뀌는 정도로 느끼게 해달라"는 표현으로 전달됨.\n\n5. 다음 단계\n편도현 - 요구사항 분석 착수 계획을 3월 첫 주까지 수립.', '요구사항 분석 착수.', NULL, '2026-02-10 09:00:00', '2026-02-10 09:00:00', NULL),
(39, 5, (SELECT id FROM users WHERE employee_no='DT22-0093'), 'MTG-2026-03-03-39', '요구사항 분석 착수 점검', '2026-03-03', '고객사(서일캐피탈 본사)', '분석 계획 공유', '편도현 컨설팅파트장 - 여신심사 프로세스 분석 계획 발표. 접수→서류검토→신용평가→승인→실행까지 12단계로 나눠 단계별 담당자 인터뷰 진행 예정.\n\n최한결 PM선임 - 현장 상주 인력 배치 확정. 탁서연 컨설팅선임이 상주 담당, 주 3회 현장 출근.\n\n탁서연 - "현장 실무진이랑 직접 소통할 채널이 있어야 분석이 빨라질 것 같습니다. 카톡방이든 뭐든 공식 채널 하나 열겠습니다."', '탁서연 - 현장 커뮤니케이션 채널 개설.', NULL, '2026-03-03 09:00:00', '2026-03-03 09:00:00', NULL),
(40, 5, (SELECT id FROM users WHERE employee_no='DT22-0098'), 'MTG-2026-03-24-40', '요구사항 분석 중간 점검', '2026-03-24', '22F 대회의실', '진행률 확인', '1. 진행률\n여신심사 프로세스 12단계 중 8단계 분석 완료.\n\n2. 괴리 발견\n채동민 컨설팅선임 - 계약 범위와 실제 요구사항 간 괴리 2건 발견. "신용평가 단계에서 외부 신용정보 조회를 실시간으로 원하시는데, 이건 계약서상 범위(배치 조회)를 벗어나는 요청입니다. 승인 단계 결재선도 계약 당시보다 실제로는 한 단계 더 있고요."\n\n3. 대응 방향\n편도현 파트장 - "계약 범위를 벗어나는 요청이니 그냥 해드릴 수는 없고, 별도 협의가 필요합니다." 안세희 컨설팅팀장이 서일캐피탈과 직접 재조정 협의를 진행하기로 함.\n\n4. 나머지 4단계\n승인·실행 단계 분석은 4월 중 완료 예정.', '안세희 - 계약 범위 재조정 서일캐피탈과 협의.', NULL, '2026-03-24 09:00:00', '2026-03-24 09:00:00', NULL),
(41, 5, (SELECT id FROM users WHERE employee_no='DT22-0093'), 'MTG-2026-06-01-41', '요구사항 분석 완료 보고', '2026-06-01', '22F 대회의실', '분석 결과 내부 공유', '1. 계약 재조정 결과\n안세희 컨설팅팀장 - 서일캐피탈과의 재조정 협의 결과 공유. 실시간 신용정보 조회는 추가 계약으로 별도 진행, 결재선 1단계 추가는 기존 범위 내 반영으로 정리됐다고 보고.\n\n2. 분석 결과 리뷰\n편도현 컨설팅파트장 - 여신심사 프로세스 12단계 전체 분석 완료. 각 단계별 소요시간, 병목 구간(신용평가 단계가 평균 처리시간의 40% 차지), 시스템화 우선순위를 정리한 결과물 공유.\n\n3. 참석자 의견\n구본재 PM실 팀장 - "분석 결과가 명확해서 설계 단계로 넘어가는 데 무리 없어 보입니다." 함가은 컨설팅선임이 심사역 인터뷰에서 나온 세부 UX 요청사항(승인 이력 한눈에 보기 등)을 별도로 정리해 설계팀에 전달하기로 함.\n\n4. 다음 단계\n아키텍처 설계 착수, 석민규 파트장이 설계 총괄.', '아키텍처 설계 착수.', NULL, '2026-06-01 09:00:00', '2026-06-01 09:00:00', NULL),
(42, 5, (SELECT id FROM users WHERE employee_no='DT22-0094'), 'MTG-2026-06-22-42', '아키텍처 설계 착수', '2026-06-22', '22F 대회의실', '설계 범위 확정', '석민규 컨설팅파트장이 아키텍처 설계 방향 3안 제시.\n- A안: 기존 코어뱅킹과 완전 분리된 신규 시스템\n- B안: 코어뱅킹 내부 모듈로 통합\n- C안: 분리하되 실시간 연동 계층을 두는 하이브리드\n\n석민규 - "고객사가 기존 방식 유지를 원했으니 완전 분리보다는 C안이 맞다고 봅니다. 다만 연동 계층 설계가 관건이에요."\n\n최진혁 컨설팅선임 - 대외연계 API 설계가 핵심 리스크라고 지적. "외부 신용정보 연동까지 얽히면 연동 지점이 많아집니다. 여기서 삐끗하면 전체 일정에 영향이 커요."\n\nC안 채택, 대외연계 API 설계를 최우선 과제로 배정.', '손민석 - 성능 요건 정의서 7/13까지.', NULL, '2026-06-22 09:00:00', '2026-06-22 09:00:00', NULL),
(43, 5, (SELECT id FROM users WHERE employee_no='DT22-0196'), 'MTG-2026-07-13-43', '아키텍처 설계 중간 점검', '2026-07-13', '22F 대회의실', '설계 진행 점검', '1. 진행률\n아키텍처 설계 60% 진행.\n\n2. 대외연계 API 프로토타입\n정예린 BE선임 - 대외연계 API 프로토타입 완료 보고. "핵심 연동 3개(신용정보, 코어뱅킹, 전자결재) 다 붙여봤는데, 응답 시간은 문제없습니다. 다만 신용정보 쪽 인증 방식이 좀 까다로워서 별도 모듈로 뺐어요."\n\n3. 보안 요건 추가\n오승택 BE선임 - 서일캐피탈 측 보안팀에서 추가 요건(전송 구간 암호화 강화)을 전달해왔다고 언급. "저희끼리 판단하기보다 정보보안팀 검토를 받는 게 나을 것 같습니다."\n\n4. 다음 단계\n최도영 정보보안팀 선임과 협의 필요, 협의 결과에 따라 설계 일정 영향 가능성 있음.', '최도영 - 보안 요건 검토 7/27까지.', NULL, '2026-07-13 09:00:00', '2026-07-13 09:00:00', NULL),
(44, 5, (SELECT id FROM users WHERE employee_no='DT24-0010'), 'MTG-2026-07-27-44', '보안 요건 반영 점검', '2026-07-27', '22F 대회의실', '보안 요건 확정', '최도영 정보보안팀 선임 검토 결과 공유. 현재 설계된 암호화 방식(TLS 1.2)으로는 서일캐피탈 보안팀 기준을 충족하지 못해 TLS 1.3 + 필드 단위 추가 암호화로 변경 필요.\n\n최도영 - "금융권 대상이라 저쪽 보안 기준이 저희 기본값보다 높습니다. 지금 반영하는 게 나중에 뜯어고치는 것보다 낫습니다."\n\n정예린 BE선임 - 변경 반영 시 설계 일정 1주 조정 필요하다고 보고. 석민규 파트장 승인.\n\n강도희 PM사원 - 현장 대응 이슈 3건 공유(테스트 계정 발급 지연, 방화벽 정책 변경 요청, 회의실 예약 충돌). 모두 행정적 사안으로 최한결 PM선임이 처리하기로 함.', '정예린 - 암호화 방식 변경 반영.', NULL, '2026-07-27 09:00:00', '2026-07-27 09:00:00', NULL),
(45, 5, (SELECT id FROM users WHERE employee_no='DT22-0094'), 'MTG-2026-08-04-45', '아키텍처 설계 완료 임박 점검', '2026-08-04', '22F 대회의실', '설계 마무리 점검', '1. 보안 요건 반영 완료\n정예린 BE선임 - TLS 1.3 및 필드 단위 암호화 반영 완료. 최도영 선임 재검토에서도 이상 없음 확인.\n\n2. 설계 진행률\n석민규 컨설팅파트장 - 전체 설계 95% 진행. 남은 5%는 문서화 및 최종 검토.\n\n3. 기술 승인 일정\n남기훈 부사장의 기술 승인을 8월 둘째 주로 예약. 석민규 - "이 규모 프로젝트는 부사장님 승인을 받고 개발 착수하는 게 저희 프로세스라서요. 문서만 제때 넘기면 일정엔 문제없을 겁니다."\n\n4. 다음 단계\n설계 문서 최종본 완성, 개발 착수 준비.', '석민규 - 설계 문서 최종본 8/11까지.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(46, 6, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'MTG-2026-04-08-46', '마이데이터 3.0 대응 킥오프', '2026-04-08', '21F 포커스룸', '규제 요건 공유 및 일정 합의', '1. 배경\n금융위 마이데이터 3.0 규격이 2027년 2월 시행 예정으로 발표됨에 따라 대응 프로젝트를 개시했다. 고은결 데이터팀장이 신규 규격의 핵심 변경점을 정리해 공유.\n- 전송 데이터 항목 12개 신규 추가(자산관리 관련)\n- 배치 전송 주기 일 1회 → 일 2회로 변경\n- 데이터 정합성 검증 절차 의무화\n\n2. 고은결 팀장 코멘트\n"마감이 명확한 규제 대응이라 일정 관리가 제일 중요합니다. 2027년 2월까지지만 저희는 내부적으로 2026년 말 완료를 목표로 잡겠습니다. 규제 대응은 항상 막판에 이슈가 생기더라고요."\n\n3. 진행 순서\n데이터 항목 매핑 → 배치 연동 설계/개발 → 데이터 검증 순으로 진행.\n\n4. 역할 분담\n정하람 선임 - 데이터 항목 매핑 총괄. 강민준 선임 - 배치 연동 설계. 오승현·배지훈·윤서아 - 개발 및 검증 지원. 강지원 선임(경영지원)이 컴플라이언스 관점에서 자문.', '데이터 항목 매핑 착수.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00', NULL),
(47, 6, (SELECT id FROM users WHERE employee_no='DT22-0104'), 'MTG-2026-04-29-47', '데이터 항목 매핑 진행 점검', '2026-04-29', '21F 포커스룸', '매핑 진행률 확인', '정하람 선임 - 데이터 항목 매핑 작업 40% 완료 보고. 신규 항목 12개 중 5개는 기존 데이터로 바로 매핑 가능, 나머지 7개는 신규 필드 추가나 계산 로직이 필요한 상태.\n\n강지원 선임(경영지원, 컴플라이언스 검토) - "가이드라인을 다시 보니 항목 2개가 더 있어야 할 것 같습니다. 자산관리 상세 카테고리 쪽인데, 필수는 아니고 권고 사항이긴 한데 나중에 감사 때 지적받느니 지금 넣는 게 낫다고 봅니다."\n\n정하람 - 추가 2개 항목 반영해서 총 14개로 매핑 범위 조정.', '정하람 - 추가 항목 반영.', NULL, '2026-04-29 09:00:00', '2026-04-29 09:00:00', NULL),
(48, 6, (SELECT id FROM users WHERE employee_no='DT22-0105'), 'MTG-2026-05-20-48', '매핑 완료 및 배치 설계 착수', '2026-05-20', '21F 포커스룸', '매핑 완료 확인', '정하람 선임 - 데이터 항목 매핑 전량(14개) 완료 보고.\n\n강민준 선임 - 배치 연동 설계 착수 보고. 일 1회에서 2회로 전송 주기가 바뀌는 만큼, 기존 배치 스케줄과의 충돌 여부를 먼저 확인 중이라고 설명. "다행히 시간대가 겹치는 배치는 없어서 큰 구조 변경 없이 갈 수 있을 것 같습니다."\n\n고은결 팀장 - 설계 완료 목표를 6/10로 제시.', '강민준 - 배치 설계 6/10까지.', NULL, '2026-05-20 09:00:00', '2026-05-20 09:00:00', NULL),
(49, 6, (SELECT id FROM users WHERE employee_no='DT23-0031'), 'MTG-2026-06-24-49', '배치 연동 진행 점검', '2026-06-24', '21F 포커스룸', '개발 진행률 확인', '배치 연동 개발 55% 진행.\n\n오승현 선임 - API 명세 검토 중 규격 해석 이견 1건 발견. "가이드라인 문구가 애매해서요. 신규 항목 중 하나가 ''해당 없음''일 때 필드를 아예 빼야 하는지 null로 채워야 하는지가 명확하지 않습니다."\n\n김태율 데이터파트장 - "애매하면 보수적으로 가는 게 맞긴 한데, 이건 금융위 가이드라인을 직접 확인하는 게 낫겠습니다. 잘못 해석했다가 나중에 전체 재작업하는 것보다는요."\n\n김태율이 직접 확인하기로 함.', '김태율 - 금융위 가이드라인 재확인.', NULL, '2026-06-24 09:00:00', '2026-06-24 09:00:00', NULL),
(50, 6, (SELECT id FROM users WHERE employee_no='DT22-0102'), 'MTG-2026-07-15-50', '배치 연동 진행 점검', '2026-07-15', '21F 포커스룸', '진행률 확인', '배치 연동 개발 완료.\n\n규격 해석 이견 처리\n김태율 데이터파트장 - 금융위 가이드라인 확인 결과 명확한 답은 없었으나, 유사 사례 검토 결과 보수적 해석(필드는 유지하고 null 처리)이 안전하다고 판단, 해당 방식으로 반영 결정.\n\n배지훈 사원 - 배치 연동 완료에 따라 데이터 검증 착수 보고. "일단 표본 데이터로 정합성부터 확인해보고, 이상 없으면 전체 범위로 넓히겠습니다."', '배지훈 - 데이터 검증 결과 8월 첫 주까지.', NULL, '2026-07-15 09:00:00', '2026-07-15 09:00:00', NULL),
(51, 6, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'MTG-2026-08-05-51', '데이터 검증 중간 점검', '2026-08-05', '21F 포커스룸', '검증 진행률 확인', '1. 검증 진행률\n데이터 검증 70% 진행. 배지훈 사원 - 전반적으로 정합성 문제는 크지 않다고 보고.\n\n2. 이상 데이터 발견\n윤서아 사원 - 정제 대상 이상 데이터 120건 발견. "대부분 예전 시스템에서 넘어온 값이 신규 항목 형식이랑 안 맞는 케이스들이에요. 데이터 자체를 고치기보다는 변환 로직에서 처리하는 게 나을 것 같습니다."\n\n3. 일정 점검\n고은결 팀장 - "규제 마감(2027.02)까지는 여유가 있지만, 저희 내부 목표는 연말입니다. 이상 데이터 건도 미루지 말고 지금 처리하고 갑시다." 지연 없이 진행할 것을 재차 강조.', '윤서아 - 이상 데이터 정제 8/19까지.', NULL, '2026-08-05 09:00:00', '2026-08-05 09:00:00', NULL),
(52, 7, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2026-03-20-52', 'FDS 엔진 v3 킥오프', '2026-03-20', '21F 포커스룸', 'v2 한계점 공유 및 v3 목표 설정', '1. v2 한계점 리뷰\n백서윤 데이터파트장이 FDS 엔진 v2 운영 2년간의 성과와 한계를 정리해 공유. 오탐률이 여전히 높아(현행 오탐률 8.2%) 정상 거래가 이상 거래로 분류되는 사례가 잦고, 이로 인한 고객 불만이 누적되고 있음.\n\n2. v3 목표\n오탐률을 기존 대비 절반 이하(4% 이하)로 낮추는 것을 핵심 목표로 합의. 실시간 처리 목표는 100ms 이내 유지.\n\n3. 참석자 의견\n서강우 BE팀장 - "모델 성능이 좋아져도 실시간 처리에서 병목이 생기면 의미가 없습니다. 이번엔 백엔드 연동도 초기 설계부터 같이 고려해야 합니다."\n고은결 데이터팀장 - v2 대비 알고리즘을 근본적으로 재검토하겠다고 밝힘. "지금까지는 룰 기반 위에 모델을 얹은 구조였는데, 이번엔 모델 중심으로 다시 짜보려고 합니다."\n\n4. 역할 분담\n마예린·박시안·신재우 - 모델 실험. 배민아·배준영 - 백엔드 연동. 조은서·남준혁 - 데이터 파이프라인.\n\n5. 배경 인지\nFDS 엔진 사업이 3년 연속 적자 사업으로 분류되어 있다는 점을 백서윤 파트장이 언급, "이번 v3 결과가 사업 존속에도 영향을 줄 수 있으니 성과를 명확한 숫자로 보여줄 필요가 있다"고 덧붙임.', '모델 실험 착수.', NULL, '2026-03-20 09:00:00', '2026-03-20 09:00:00', NULL),
(53, 7, (SELECT id FROM users WHERE employee_no='DT24-0040'), 'MTG-2026-04-10-53', '모델 실험 진행 점검', '2026-04-10', '21F 포커스룸', '실험 진행 상황 공유', '박시안 사원 - 신규 알고리즘 3종(랜덤포레스트 개선형, 그래디언트 부스팅, 딥러닝 기반 앙상블) 실험 결과 공유.\n- 그래디언트 부스팅 계열: 오탐률 기존 대비 12% 개선\n- 딥러닝 앙상블: 개선폭은 비슷하나 추론 시간이 3배 이상 소요\n- 랜덤포레스트 개선형: 개선폭 미미\n\n박시안 - "그래디언트 부스팅이 성능과 속도 균형이 제일 좋습니다. 딥러닝 쪽은 성능은 나쁘지 않은데 지금 목표인 100ms 안에 들어오기가 어려워 보입니다."\n\n마예린 선임 - 그래디언트 부스팅 계열을 정밀 튜닝해보겠다고 제안, "12%도 좋은데 하이퍼파라미터를 더 다듬으면 여지가 있어 보입니다."', '마예린 - 그래디언트 부스팅 모델 정밀 튜닝 착수.', NULL, '2026-04-10 09:00:00', '2026-04-10 09:00:00', NULL),
(54, 7, (SELECT id FROM users WHERE employee_no='DT24-0040'), 'MTG-2026-05-01-54', '모델 선정 회의', '2026-05-01', '21F 포커스룸', '최종 모델 아키텍처 확정', '마예린 선임 - 그래디언트 부스팅 모델 튜닝 결과 오탐률 18% 개선 달성 보고(목표였던 절반 이하에는 못 미치지만 v2 대비 유의미한 개선). "피처 엔지니어링 쪽을 더 손보면 추가 개선 여지는 있습니다만, 지금 수준에서도 충분히 의미 있는 결과라 생각합니다."\n\n백서윤 데이터파트장 - 그래디언트 부스팅 모델을 v3 최종 모델로 확정. 남은 개선은 운영하면서 점진적으로 진행하는 것으로 방향 정리.\n\n배민아 BE선임 - 백엔드 연동 설계 착수 보고. "모델이 확정됐으니 이제 이걸 실시간으로 어떻게 서빙할지가 관건입니다."', '배민아 - 연동 설계 5/22까지.', NULL, '2026-05-01 09:00:00', '2026-05-01 09:00:00', NULL),
(55, 7, (SELECT id FROM users WHERE employee_no='DT22-0205'), 'MTG-2026-05-22-55', '백엔드 연동 설계 점검', '2026-05-22', '21F 포커스룸', '연동 설계 검토', '배준영 BE선임이 모델 서빙 아키텍처 초안 제시. 거래 요청이 들어오면 모델 서버에 실시간 조회 후 결과를 반환하는 구조.\n\n성능 이슈\n실시간 처리 목표(100ms 이내) 대비 현재 설계로는 150ms가 예상됨. 배준영 - "모델 자체 추론은 빠른데, 네트워크 왕복이랑 피처 조회하는 부분에서 시간이 더 걸립니다. 피처를 미리 캐싱해두는 방향으로 최적화가 필요할 것 같습니다."\n\n서강우 BE팀장 - 최적화 방향에 동의, 다음 스프린트에서 집중 진행하도록 지시.', '배준영 - 서빙 아키텍처 최적화.', NULL, '2026-05-22 09:00:00', '2026-05-22 09:00:00', NULL),
(56, 7, (SELECT id FROM users WHERE employee_no='DT22-0082'), 'MTG-2026-06-12-56', '사업성 재검토 회의', '2026-06-12', '22F 대회의실', '사업본부 우려 대응', '1. 배경\n노진우 사업기획팀장 부재로 오채린 사업기획파트장이 참석. FDS 엔진 사업이 3년 연속 적자를 기록 중인 상황에서, v3 투자 대비 실질적 개선 효과가 있는지 재검토가 필요하다는 사업본부 문제 제기로 소집된 자리.\n\n2. 오채린 파트장 발언\n"기술적으로 좋아지는 건 알겠는데, 저희 쪽에서 봐야 하는 건 결국 손익입니다. 지금까지는 매년 투자만 하고 회수가 안 되는 그림이었는데, 이번엔 뭐가 다른지 숫자로 보여주셔야 사업본부 설득이 가능합니다."\n\n3. 대응 (최재훈 사업기획선임)\n최재훈이 v2 대비 개선된 탐지 성능 지표를 근거로 존속 논리를 정리해 발표. 오탐률 개선(18%)에 따른 고객 이탈 방지 효과, 이상 거래 탐지율 개선에 따른 손실 방지 금액을 추산해 제시. "정확한 회수 시점은 아직 단정하기 어렵지만, 방향성 자체는 명확히 개선되고 있습니다."\n\n4. 백서윤 데이터파트장 발언\n"기술 지표로는 확실히 좋아지고 있습니다. 다만 손익으로 연결되려면 운영 데이터가 더 쌓여야 정확한 판단이 가능합니다."\n\n5. 결론\n즉각적인 사업 중단 결정은 없었으나, 다음 분기 손익 시나리오를 갱신해 재보고하기로 함. 프로젝트는 예정대로 진행.', '최재훈 - 손익 시나리오 갱신본 공유.', NULL, '2026-06-12 09:00:00', '2026-06-12 09:00:00', NULL),
(57, 7, (SELECT id FROM users WHERE employee_no='DT22-0205'), 'MTG-2026-07-03-57', '서빙 최적화 완료 점검', '2026-07-03', '21F 포커스룸', '성능 목표 달성 확인', '배준영 BE선임 - 서빙 아키텍처 최적화 완료 보고. 피처 사전 캐싱 방식 적용으로 실시간 처리 92ms 달성, 목표(100ms 이내) 충족.\n\n배준영 - "캐싱 TTL을 짧게(1분) 잡아서 최신성도 크게 해치지 않으면서 속도를 확보했습니다."\n\n조은서 데이터선임 - 파이프라인 안정화 착수 보고. 모델 서빙과 데이터 파이프라인 간 연동 부분에서 안정성 검증이 필요하다고 설명.\n\n사업성 재검토 후속으로, 백서윤 파트장이 이번 성능 달성 결과도 다음 손익 보고에 포함하자고 언급.', '조은서 - 파이프라인 안정화 7/24까지.', NULL, '2026-07-03 09:00:00', '2026-07-03 09:00:00', NULL),
(58, 7, (SELECT id FROM users WHERE employee_no='DT22-0109'), 'MTG-2026-07-24-58', '파이프라인 안정화 점검', '2026-07-24', '21F 포커스룸', '안정화 진행 확인', '조은서 데이터선임 - 데이터 파이프라인 안정화 80% 완료 보고.\n\n남준혁 데이터선임 - 잔여 이슈 2건 공유.\n1) 피크 시간대(오전 9~10시) 트래픽 급증 시 파이프라인 지연 간헐적 발생\n2) 특정 거래 유형(해외 카드 거래)에서 피처 계산이 늦게 반영되는 케이스\n\n남준혁 - "1번은 자원 스케일링으로 대응 가능할 것 같은데, 2번은 원인을 좀 더 봐야 합니다. 해외 거래는 환율 정보가 얽혀 있어서요."', '남준혁 - 잔여 이슈 8/7까지.', NULL, '2026-07-24 09:00:00', '2026-07-24 09:00:00', NULL),
(59, 7, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2026-08-04-59', '8월 정기 점검', '2026-08-04', '21F 포커스룸', '종합 진행률 점검', '1. 파이프라인 안정화 완료\n남준혁 데이터선임 - 잔여 이슈 2건 모두 해결 완료 보고. 피크 시간대 이슈는 자원 스케일링으로, 해외 거래 이슈는 환율 정보 캐싱 방식 개선으로 해결.\n\n2. 종합 진행률\n백서윤 데이터파트장 - 모델·백엔드 연동·파이프라인 모두 완료, 남은 것은 오탐률 개선 목표(4% 이하) 최종 검증뿐이라고 보고. 현재 운영 데이터 기준으로는 4.3% 수준으로 근접.\n\n3. 상품화 방향\n위성현 사업기획파트장 - 상품화 방향 기획 초안 공유. 자사 사용뿐 아니라 향후 관계사 대상 서비스 확장 가능성을 언급. "아직 초안 단계지만, 이번 v3 결과가 좋으면 사업성 재검토 때 나왔던 우려도 자연스럽게 해소될 것 같습니다."\n\n4. 다음 단계\n최종 오탐률 검증 결과를 다음 회의에서 확정 보고하기로 함.', '위성현 - 상품화 기획안 다음 회의 공유.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(60, 8, (SELECT id FROM users WHERE employee_no='DT22-0024'), 'MTG-2026-07-03-60', 'ISMS-P 갱신 준비 킥오프', '2026-07-03', '21F 관제센터', '감사 대응 일정 수립', '류경호 보안팀장 주관.\n\n작년 지적사항 리뷰\n작년 인증 심사에서 나온 권고사항 3건(접근권한 관리 로그 보관 기간 미흡, 일부 서버 패치 주기 초과, 비상연락망 최신화 누락)을 다시 짚었다. 전부 경미 사항으로 재발 여부만 확인하면 되는 수준.\n\n일정\n기술 취약점 점검을 우선 진행하고, 그 결과를 바탕으로 감사 대응 자료를 준비하기로 함. 서준혁 파트장이 점검 총괄, 백승아 파트장이 문서 작업 총괄.\n\n부서별 협조 요청\n권영달 CISO(서면 공유) - 각 부서 접근권한 현황 자료 제출 기한을 7/17까지로 요청. 임재현 선임(경영지원)이 부서별 공지 발송 담당.', '기술 취약점 점검 착수.', NULL, '2026-07-03 09:00:00', '2026-07-03 09:00:00', NULL),
(61, 8, (SELECT id FROM users WHERE employee_no='DT22-0039'), 'MTG-2026-07-24-61', '기술 취약점 점검 결과 보고', '2026-07-24', '21F 관제센터', '점검 결과 공유', '서준혁 보안파트장 - 기술 취약점 점검 결과 경미한 항목 4건 발견 보고.\n1) 일부 개발 서버 OS 패치 2개월 지연\n2) 퇴사자 계정 3건 미회수 확인(모두 접근 이력 없음)\n3) 로그 보관 정책이 문서상 기준과 실제 설정 값 불일치\n4) 방화벽 정책 중 미사용 룰 5건 방치\n\n서준혁 - "전부 심각한 건 아니고 관리 소홀에 가까운 항목들입니다. 다 조치 가능한 수준이니 심사 전까지 정리하면 됩니다."\n\n백승아 보안파트장 - 감사 대응 자료 초안 작성 중이라고 보고, 발견 항목 4건에 대한 조치 계획도 함께 포함하겠다고 언급.', '서준혁 - 발견 항목 4건 8/14까지 조치.', NULL, '2026-07-24 09:00:00', '2026-07-24 09:00:00', NULL),
(62, 9, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2026-02-09-62', '판교 DC 이중화 2단계 킥오프', '2026-02-09', '판교 데이터센터', '1단계 이후 확장 범위 합의', '1. 배경\n2024년 완료된 판교 DC 이중화 1단계(서버 이중화)에 이어, 네트워크·전원 계통까지 이중화하는 2단계를 착수했다. 진병호 인프라팀장이 1단계 완료 후에도 회선 장애 시 단일 장애점(SPOF)이 남아있다는 점을 배경으로 설명.\n\n2. 범위 합의\n- 네트워크 이중화(회선사업자 이원화, 라우팅 이중화)\n- 전원 이중화(UPS 계통 점검 및 보강)\n\n3. 진병호 팀장 코멘트\n"1단계 때 서버는 이중화했는데 정작 회선이 하나면 의미가 반감됩니다. 이번엔 그 구멍을 메우는 게 목표입니다."\n\n4. 역할 분담\n서인호 파트장 - 네트워크 이중화 설계 총괄. 지동원 파트장 - 시공 관련 총괄. 방윤아·하도경 - 실무 지원.\n\n5. 일정\n설계 → 회선사업자/시공업체 선정 → 시공 순으로 진행, 연내 완료를 목표로 함.', '설계안 작성.', NULL, '2026-02-09 09:00:00', '2026-02-09 09:00:00', NULL),
(63, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), 'MTG-2026-03-02-63', '네트워크 이중화 설계 점검', '2026-03-02', '판교 데이터센터', '설계 진행 확인', '서인호 인프라파트장이 네트워크 이중화 설계안 초안 공유. 기존 회선사업자(A사) 외 물리적으로 다른 경로를 쓰는 회선사업자를 추가로 확보하는 방향.\n\n서인호 - "같은 사업자 안에서 이중화해봐야 같은 국사, 같은 관로를 쓰면 소용없습니다. 물리적으로 완전히 분리된 경로가 있는 사업자를 찾아야 진짜 이중화입니다."\n\n추가 회선사업자 검토 필요성 제기, 후보 조사 착수하기로 함.', '서인호 - 추가 회선사업자 후보 조사.', NULL, '2026-03-02 09:00:00', '2026-03-02 09:00:00', NULL),
(64, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), 'MTG-2026-03-23-64', '회선사업자 선정 회의', '2026-03-23', '판교 데이터센터', '회선사업자 확정', '서인호 인프라파트장 - 회선사업자 후보 3곳 비교 결과 공유. 경로 분리 여부, 비용, SLA 기준으로 B사를 최종 선정.\n\n서인호 - "B사가 저희 기존 A사 경로랑 물리적으로 완전히 분리돼 있는 걸 확인했습니다. SLA도 99.95%로 나쁘지 않고요."\n\n방윤아 인프라선임 - 이중화 작업에 필요한 장비·회선 자산 목록 갱신 작업 진행률 30% 보고. "장비가 워낙 오래돼서 자산대장이랑 실물이 안 맞는 것들이 꽤 있어서 하나씩 확인하고 있습니다."\n\nB사와 계약 협의 착수하기로 함.', '서인호 - B사 계약 협의.', NULL, '2026-03-23 09:00:00', '2026-03-23 09:00:00', NULL),
(65, 9, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2026-04-30-65', '네트워크 이중화 설계 완료 보고', '2026-04-30', '판교 데이터센터', '설계 완료 확인', '네트워크 이중화 설계 완료, B사와 계약 체결 완료.\n\n서인호 인프라파트장 - "설계는 다 끝났고, 이제 실제로 회선 깔고 라우팅 설정하는 시공 단계로 넘어갑니다."\n\n진병호 인프라팀장 - 시공 업체 선정 절차 착수 지시. "시공은 실제 데이터센터에 들어가서 하는 작업이라 업체 검증을 꼼꼼히 해주세요. 작업 중 실수 하나가 바로 장애로 이어질 수 있는 영역입니다."\n\n지동원 파트장이 시공 업체 선정 절차를 맡기로 함.', '지동원 - 시공 업체 선정 절차 착수.', NULL, '2026-04-30 09:00:00', '2026-04-30 09:00:00', NULL),
(66, 9, (SELECT id FROM users WHERE employee_no='DT22-0058'), 'MTG-2026-05-21-66', '시공 업체 선정 점검', '2026-05-21', '판교 데이터센터', '업체 선정 진행 확인', '지동원 인프라파트장 - 시공 업체 3곳 견적 비교 결과 공유. 비용, 데이터센터 시공 경력, 보유 인증(전기안전관리 등) 기준으로 검토.\n\n지동원 - "가격만 보면 제일 싼 곳이 눈에 들어오는데, 데이터센터 시공 경력이 짧아서 좀 불안합니다. 경력 있는 두 곳으로 압축했습니다."\n\n최종 후보 2곳으로 압축, 다음 회의 전까지 현장 실사 후 최종 결정하기로 함.', '지동원 - 최종 업체 선정 6/4까지.', NULL, '2026-05-21 09:00:00', '2026-05-21 09:00:00', NULL),
(67, 9, (SELECT id FROM users WHERE employee_no='DT22-0058'), 'MTG-2026-06-18-67', '실무 준비 점검', '2026-06-18', '판교 데이터센터', '시공 준비 상태 확인', '지동원 인프라파트장 - 현장 실사 결과를 반영해 시공 업체 최종 확정 보고. "두 곳 다 현장 가서 실제로 어떻게 작업하는지 보고 왔는데, 저희가 원하는 무중단 작업 경험이 있는 쪽으로 정했습니다."\n\n하도경 인프라사원 - 시공 전 현장 준비 사항 점검. 전원 차단 없이 진행해야 하는 작업 구간, 접근 통제 절차, 비상 연락 체계 등을 정리 중이라고 보고. "데이터센터 안에서 하는 작업이라 체크리스트를 꼼꼼하게 만들고 있습니다."', '하도경 - 시공 전 현장 점검 체크리스트 작성.', NULL, '2026-06-18 09:00:00', '2026-06-18 09:00:00', NULL),
(68, 9, (SELECT id FROM users WHERE employee_no='DT22-0061'), 'MTG-2026-07-20-68', '실무 착수 점검', '2026-07-20', '판교 데이터센터', '진행 상황 확인', '방윤아 인프라선임 - 자산 목록 갱신 작업 완료 결과 공유. 실물과 불일치했던 항목 18건을 모두 바로잡아 최신화 완료.\n\n하도경 인프라사원 - 현장 점검 체크리스트 완성, 시공 업체와 최종 리허설 진행 완료 보고.\n\n서인호 인프라파트장 - 모든 사전 준비가 끝났다고 판단, 네트워크 이중화 시공 일정을 8월 첫 주로 확정.', '네트워크 이중화 시공 일정 확정.', NULL, '2026-07-20 09:00:00', '2026-07-20 09:00:00', NULL),
(69, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), 'MTG-2026-08-04-69', '이중화 구축 착수 점검', '2026-08-04', '판교 데이터센터', '시공 착수 확인', '네트워크 이중화 시공이 예정대로 착수됐다.\n\n서인호 인프라파트장 - 1일차 작업 진행 상황 공유. B사 신규 회선 포설 작업 완료, 라우팅 이중화 설정은 다음 주부터 순차 진행 예정.\n\n배주안 PM실 사원 - 전체 일정표 상 별도 리스크 요인 없음을 보고. "지금까지는 계획대로 가고 있고, 큰 변수는 안 보입니다."\n\n진병호 인프라팀장 - "무중단으로 진행 중인 만큼 이상 징후 있으면 바로 공유해주세요." 격주 진행률 보고 체계 유지하기로 함.', '서인호 - 시공 진행률 격주 보고.', NULL, '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(70, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2024-02-05-70', '판교 DC 이중화 1단계 킥오프', '2024-02-05', '판교 데이터센터', 'SPOF 제거 범위 합의', '1. 배경\n판교 데이터센터 운영 점검 과정에서 서버·스토리지 단일 장애점(SPOF)이 다수 확인됨에 따라 이중화 프로젝트를 시작했다. 진병호 인프라팀장 - "지금 구조는 핵심 서버 하나만 죽어도 서비스 전체가 멈출 수 있는 상태입니다. 우선순위를 정해서 순차적으로 없애야 합니다."\n\n2. 우선순위 결정\n영향도(장애 시 전사 서비스 영향 범위)와 발생 가능성을 기준으로 우선순위를 매겼다. 1순위 핵심 API 서버군, 2순위 인증 서버, 3순위 스토리지로 결정.\n\n3. 역할 분담\n서인호 파트장 - 서버 이중화 설계. 지동원 파트장 - 시공 및 실무 총괄.\n\n4. 일정\n연내 완료를 목표로, 설계 → 시공 순으로 단계적 진행하기로 함.', '설계 착수.', NULL, '2024-02-05 09:00:00', '2024-02-05 09:00:00', NULL),
(71, 10, (SELECT id FROM users WHERE employee_no='DT22-0065'), 'MTG-2024-03-11-71', 'SPOF 제거 설계 점검', '2024-03-11', '판교 데이터센터', '설계 진행 확인', '서인호 인프라파트장이 서버 이중화 설계안 공유. 핵심 API 서버군과 인증 서버를 액티브-액티브 구성으로 전환하는 안.\n\n서인호 - "서버 쪽은 방향이 명확한데, 스토리지는 얘기가 좀 다릅니다. 지금 쓰는 스토리지가 이중화를 기본 지원하는 모델이 아니라서, 방식 자체를 다시 검토해야 할 것 같습니다."\n\n스토리지는 별도 검토 필요성 제기, 지동원 파트장이 방안 조사하기로 함.', '지동원 - 스토리지 이중화 방안 조사.', NULL, '2024-03-11 09:00:00', '2024-03-11 09:00:00', NULL),
(72, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2024-04-15-72', '스토리지 이중화 방안 확정', '2024-04-15', '판교 데이터센터', '설계 최종 확정', '지동원 인프라파트장 - 스토리지 이중화 방식 조사 결과 공유. 액티브-액티브는 현재 장비로 지원 불가, 액티브-스탠바이 방식으로 결정.\n\n지동원 - "완전한 무중단은 아니지만, 장애 시 전환 시간을 수 분 이내로 줄일 수 있습니다. 지금보다는 훨씬 나은 수준이라 이걸로 가는 게 맞다고 봅니다."\n\n서인호 파트장 - 서버·스토리지 설계 모두 최종 확정, 예산안 준비 필요성 언급.\n\n진병호 인프라팀장 - 예산안을 정리해 하수민 본부장에게 직접 보고하겠다고 밝힘.', '진병호 - 예산안 하수민 본부장 보고.', NULL, '2024-04-15 09:00:00', '2024-04-15 09:00:00', NULL),
(73, 10, (SELECT id FROM users WHERE employee_no='DT22-0058'), 'MTG-2024-05-20-73', '시공 착수 점검', '2024-05-20', '판교 데이터센터', '시공 진행 확인', '예산 승인 완료에 따라 서버 이중화 시공에 착수했다.\n\n지동원 인프라파트장 - 초기 진행 상황 공유. 핵심 API 서버군 이중화 작업이 계획대로 진행 중이며 별다른 이슈 없음.\n\n지동원 - "일단 초반은 순조롭습니다. 무중단으로 진행해야 하는 부분이라 신경은 쓰이지만, 지금까지는 계획대로예요."', '지동원 - 시공 진행률 격주 보고.', NULL, '2024-05-20 09:00:00', '2024-05-20 09:00:00', NULL),
(74, 10, (SELECT id FROM users WHERE employee_no='DT22-0065'), 'MTG-2024-07-01-74', '시공 중간 점검', '2024-07-01', '판교 데이터센터', '진행률 확인', '서인호 인프라파트장 - 서버 이중화 80% 완료 보고. "핵심 API 서버군은 다 끝났고, 인증 서버 쪽만 남았는데 이번 달 안에 마무리될 것 같습니다."\n\n서버 이중화 완료를 앞두고 스토리지 이중화 착수. 서인호 - "서버가 먼저 끝나서 다행입니다. 이제 스토리지로 넘어가겠습니다."', '서인호 - 스토리지 이중화 8월 말까지.', NULL, '2024-07-01 09:00:00', '2024-07-01 09:00:00', NULL),
(75, 10, (SELECT id FROM users WHERE employee_no='DT22-0058'), 'MTG-2024-08-19-75', '구축 마무리 점검', '2024-08-19', '판교 데이터센터', '최종 검증 준비', '지동원 인프라파트장 - 서버·스토리지 이중화 전량 완료 보고.\n\n지동원 - "이제 설계랑 시공은 다 끝났고, 실제로 장애 상황을 흉내 내서 제대로 전환되는지 테스트만 남았습니다."\n\n무중단 전환 테스트 일정 수립. 실제 트래픽이 있는 상태에서 진행해야 하는 만큼 새벽 시간대로 잡기로 함.', '지동원 - 전환 테스트 9/15까지.', NULL, '2024-08-19 09:00:00', '2024-08-19 09:00:00', NULL),
(76, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2024-09-25-76', '1단계 완료 보고', '2024-09-25', '21F 대회의실', '프로젝트 종료 보고', '1. 전환 테스트 결과\n진병호 인프라팀장 - 무중단 전환 테스트 결과 공유. 서버는 예상대로 무중단 전환 확인, 스토리지는 액티브-스탠바이 방식이라 평균 전환 시간 40초로 측정됐으나 목표(수 분 이내)를 크게 상회하는 결과.\n\n2. 프로젝트 종료\n서인호·지동원 파트장 - 계획했던 SPOF 항목 전량 이중화 완료 확인. "1단계 목표였던 핵심 SPOF는 다 없앴습니다. 남은 건 회선이나 전원 쪽인데, 그건 규모가 더 커서 별도 프로젝트로 가는 게 맞을 것 같습니다."\n\n3. 다음 단계\n진병호 팀장 - 회선·전원 이중화를 다루는 2단계 프로젝트를 별도로 기획 검토하겠다고 밝힘.', '2단계 기획 검토.', NULL, '2024-09-25 09:00:00', '2024-09-25 09:00:00', NULL),
(77, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), 'MTG-2024-03-06-77', '그룹 통합인증 킥오프', '2024-03-06', '22F 포커스룸', '통합 인증 범위 합의', '1. 배경\n다온뱅크·다온증권·다온페이 각각 별도 로그인을 쓰고 있어, 계열사를 넘나드는 고객이 매번 재로그인해야 하는 불편이 지속 제기됐다. 서윤호 BE파트장 - "고객 입장에선 다 한 그룹인데 로그인만 세 번 하는 셈이니, 이번에 통합 인증(SSO)으로 묶어보려는 겁니다."\n\n2. 범위 합의\n다온뱅크·증권·페이 세 서비스의 로그인을 통합, 하나의 계정으로 세 서비스를 오가도 재로그인 없이 이용 가능하도록 하는 것을 목표로 함.\n\n3. 팀 구성\n서윤호 파트장 총괄, 문가연·최시훈·임도현·배서현 선임 4명이 함께 진행. 소규모 팀이라 파트 구분 없이 전원이 설계부터 개발까지 함께 참여하는 방식으로 진행하기로 함.\n\n4. 일정\n설계 → 개발 → 서비스별 연동 테스트 순으로 진행.', '설계 착수.', NULL, '2024-03-06 09:00:00', '2024-03-06 09:00:00', NULL),
(78, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), 'MTG-2024-03-27-78', '설계 진행 점검', '2024-03-27', '22F 포커스룸', '설계 방향 확인', '서윤호 BE파트장 - SSO 아키텍처 초안 공유. 중앙 인증 서버를 두고 각 서비스가 여기에 토큰 기반으로 인증을 위임하는 구조.\n\n토큰 발급 방식 논의\n세션 기반과 토큰(JWT) 기반을 비교 검토한 끝에 JWT로 채택. 서윤호 - "세 개 서비스가 서로 다른 서버군에서 도는데, 세션 방식은 공유가 번거롭습니다. JWT면 서버 간 상태 공유 없이도 검증이 가능해서 구조가 훨씬 단순해집니다."\n\n최시훈 BE선임이 토큰 발급 로직 설계를 맡기로 함.', '최시훈 - 토큰 발급 로직 설계.', NULL, '2024-03-27 09:00:00', '2024-03-27 09:00:00', NULL),
(79, 11, (SELECT id FROM users WHERE employee_no='DT22-0184'), 'MTG-2024-04-17-79', '권한 범위 1차 협의', '2024-04-17', '22F 포커스룸', '권한 범위 정의', '문가연 BE선임 - 서비스별 권한 범위(토큰 스코프) 초안 제시. 은행·증권·페이 각각 접근 가능한 API 범위를 정의.\n\n문가연 - "일단 각 서비스가 필요한 만큼만 접근하게 스코프를 나눠봤는데, 이게 보안 쪽 기준이랑 맞는지는 저희끼리 판단하기 애매한 부분이 있습니다."\n\n토큰에 담기는 권한 범위가 넓으면 보안 리스크가 될 수 있다는 우려가 나와, 정보보안팀 검토가 필요하다는 의견이 제기됨.', '문가연 - 정보보안팀에 검토 요청.', NULL, '2024-04-17 09:00:00', '2024-04-17 09:00:00', NULL),
(80, 11, (SELECT id FROM users WHERE employee_no='DT22-0186'), 'MTG-2024-05-08-80', '개발 착수 점검', '2024-05-08', '22F 포커스룸', '개발 진행 확인', '정보보안팀 검토 결과를 기다리는 동안 개발 가능한 부분부터 착수했다.\n\n임도현 BE선임 - 로그인 통합 화면 개발 담당. "화면은 세 서비스 로고를 다 보여주면서 하나의 로그인 폼으로 처리하는 형태로 만들고 있습니다."\n\n배서현 BE선임 - 서비스별 연동 테스트 계획 수립 중이라고 보고. "각 서비스마다 인증 연동하는 시점이 다를 수 있어서, 순차 배포를 고려한 테스트 시나리오를 짜고 있습니다."', '배서현 - 서비스별 연동 테스트 계획.', NULL, '2024-05-08 09:00:00', '2024-05-08 09:00:00', NULL),
(81, 11, (SELECT id FROM users WHERE employee_no='DT22-0184'), 'MTG-2024-06-18-81', '권한 범위 조율 회의', '2024-06-18', '22F 포커스룸', '정보보안팀과 권한 범위 이견 조율', '1. 정보보안팀 검토 결과\n정보보안팀에서 토큰 권한 스코프가 지나치게 넓다는 의견을 전달. 특히 은행 서비스 토큰에 증권·페이 API 접근 권한까지 광범위하게 포함된 부분을 지적.\n\n2. 이견\n문가연 BE선임 - "사용성을 위해선 어느 정도 넓게 가는 게 편한데, 보안 쪽에서는 최소 권한 원칙을 강조하시더라고요. 서로 입장이 다른 부분이라 조율이 필요합니다."\n\n정보보안팀 측(서면 의견) - 토큰 하나에 모든 권한을 담기보다, 서비스 전환 시점마다 필요한 권한만 재발급하는 방식을 제안.\n\n3. 논의\n서윤호 파트장 - "완전히 보안팀 안대로 가면 사용자가 서비스 넘어갈 때마다 살짝 지연이 생길 수 있는데, 그것도 감수할 만한지 우리끼리 먼저 정리해봅시다." 절충 방향(최소 권한 + 캐싱으로 지연 최소화)을 논의했으나 이날 결론은 못 냄.\n\n4. 다음 단계\n문가연이 절충안 초안을 만들어 정보보안팀과 재협의하기로 함.', '절충안 도출 후 재검토.', NULL, '2024-06-18 09:00:00', '2024-06-18 09:00:00', NULL),
(82, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), 'MTG-2024-07-16-82', '절충안 적용 점검', '2024-07-16', '22F 포커스룸', '절충안 반영 확인', '문가연 BE선임 - 정보보안팀과 합의한 절충안 공유. 최소 권한 원칙을 따르되, 짧은 TTL의 권한 캐싱을 둬서 서비스 전환 시 체감 지연을 최소화하는 방식으로 합의.\n\n문가연 - "보안팀도 캐싱 TTL을 짧게(30초) 두는 조건으로 동의해주셨습니다. 사용자 입장에서는 체감이 거의 안 될 정도로 지연이 작습니다."\n\n절충안 반영 완료, 중단됐던 개발을 재개했다. 임도현 BE선임 - 잔여 개발 항목(권한 재발급 로직 등) 정리해 공유.', '임도현 - 잔여 개발 8월 초까지.', NULL, '2024-07-16 09:00:00', '2024-07-16 09:00:00', NULL),
(83, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), 'MTG-2024-08-31-83', '오픈 완료 보고', '2024-08-31', '22F 포커스룸', '프로젝트 종료 보고', '1. 오픈 결과\n다온뱅크·증권·페이 로그인 통합 완료, 예정대로 오픈 진행. 서윤호 BE파트장 - 오픈 직후 초기 오류 모니터링 결과 특이 이슈 없음을 확인.\n\n2. 회고\n문가연 BE선임 - "권한 범위 이견 조율에 시간이 좀 걸렸지만, 결과적으로는 보안이랑 사용성 둘 다 챙긴 구조가 나온 것 같습니다."\n최시훈 BE선임 - 토큰 발급 로직이 안정적으로 동작 중이라고 보고.\n\n3. 후속 계획\n문가연 - 오픈 후 1개월간 안정화 모니터링을 담당하기로 함. 이상 징후 발견 시 즉시 공유하는 것으로 정리.', '문가연 - 1개월 안정화 모니터링.', NULL, '2024-08-31 09:00:00', '2024-08-31 09:00:00', NULL),
(84, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2024-09-06-84', '동해저축은행 착수 회의', '2024-09-06', '고객사(동해저축은행 본사)', '계약 범위 및 일정 합의', '1. 계약 범위 확정\n동해저축은행 여신관리 시스템 재구축 범위를 고객사와 확정했다. 여신 접수부터 사후관리까지 전체 프로세스를 신규 시스템으로 전환, 기존 레거시 데이터 이관 포함.\n\n2. 안세희 컨설팅팀장 코멘트\n"레거시가 15년 넘은 시스템이라 데이터 이관이 이번 프로젝트에서 제일 리스크가 큰 부분일 겁니다. 화면·프로세스는 저희가 많이 해본 영역이라 크게 걱정 안 하는데, 데이터 쪽은 처음부터 신경 써서 봐야 합니다."\n\n3. 역할 분담\n권도영 선임 - 여신관리 프로세스 분석 및 현장 상주. 홍재현 선임 - 데이터 이관 총괄. 여도경 선임 - 화면 요구사항 분석 지원.\n\n4. 일정\n요구사항 분석(1개월) → 개발(3개월) → 이관 리허설 → 오픈 순으로, 다음 해 상반기 완료를 목표로 함.', '요구사항 분석 착수.', NULL, '2024-09-06 09:00:00', '2024-09-06 09:00:00', NULL),
(85, 12, (SELECT id FROM users WHERE employee_no='DT22-0095'), 'MTG-2024-09-27-85', '요구사항 분석 착수 점검', '2024-09-27', '고객사(동해저축은행 본사)', '분석 계획 공유', '권도영 컨설팅선임 - 여신관리 프로세스 분석 계획 발표, 이번 주부터 현장 상주 시작. "접수, 심사, 실행, 사후관리 네 단계로 나눠서 단계별로 실무자 인터뷰부터 진행하겠습니다."\n\n홍재현 컨설팅선임 - 데이터 이관 대상 시스템 목록화 착수 보고. "레거시 시스템이 여러 번 증축된 흔적이 있어서, 지금 뭐가 살아있는 테이블이고 뭐가 죽은 테이블인지부터 가려내야 할 것 같습니다."\n\n여도경 컨설팅선임 - 기존 화면 캡처 및 기능 목록화 작업 진행 중이라고 보고.', '홍재현 - 데이터 이관 대상 시스템 목록화.', NULL, '2024-09-27 09:00:00', '2024-09-27 09:00:00', NULL),
(86, 12, (SELECT id FROM users WHERE employee_no='DT22-0095'), 'MTG-2024-10-18-86', '요구사항 분석 완료 보고', '2024-10-18', '고객사(동해저축은행 본사)', '분석 결과 공유', '권도영 컨설팅선임 - 여신관리 화면 요구사항 정의서 확정 발표. 4단계 프로세스, 총 32개 화면으로 구성. "기존 화면 대비 절반 가까이 줄였습니다. 중복 기능이랑 안 쓰는 화면이 꽤 있었더라고요."\n\n홍재현 컨설팅선임 - 데이터 이관 계획 초안 완료 보고. 이관 대상 테이블 87개 중 실제 살아있는 데이터는 61개로 확인. "나머지 26개는 예전에 쓰다가 방치된 것들이라 이관 대상에서 제외했습니다."\n\n여도경 컨설팅선임 - 화면 요구사항 정의서에 반영된 UX 개선 사항(여신 이력 한 화면에서 조회 등) 공유.\n\n다음 단계로 데이터 이관 스크립트 개발 착수.', '홍재현 - 데이터 이관 스크립트 개발 착수.', NULL, '2024-10-18 09:00:00', '2024-10-18 09:00:00', NULL),
(87, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2024-12-06-87', '개발 중간 점검', '2024-12-06', '고객사(동해저축은행 본사)', '개발 진행률 확인', '1. 개발 진행률\n여신관리 화면 개발 60% 완료. 권도영 컨설팅선임 - "확정된 32개 화면 중 19개 완료됐고, 나머지도 순조롭게 진행 중입니다."\n\n2. 데이터 이관 준비\n홍재현 컨설팅선임 - 이관 스크립트 개발 진행 중, 61개 테이블 중 40개 완료.\n\n3. 고객사 반응\n안세희 컨설팅팀장 - "고객사 담당자분들이 중간중간 화면 보여드릴 때마다 만족도가 양호합니다. 특히 여신 이력 조회 화면 반응이 좋았어요." 다만 세부 필드 요청이 조금씩 늘고 있어 범위 관리는 계속 신경 써야 한다고 언급.\n\n4. 다음 단계\n권도영 - 잔여 화면 개발을 1월 중 완료하기로 함.', '권도영 - 잔여 화면 개발 1월 중 완료.', NULL, '2024-12-06 09:00:00', '2024-12-06 09:00:00', NULL),
(88, 12, (SELECT id FROM users WHERE employee_no='DT23-0027'), 'MTG-2025-01-17-88', '데이터 이관 리허설', '2025-01-17', '고객사(동해저축은행 본사)', '이관 리스크 점검', '1. 리허설 진행\n데이터 이관 리허설을 실제 이관 스크립트로 진행했다.\n\n2. 정합성 오류 발견\n홍재현 컨설팅선임 - 리허설 중 일부 레거시 데이터 정합성 오류 발견. "여신 실행일자가 없는데 완료 상태로 표시된 건이 340건 정도 있었습니다. 예전에 수기로 처리하고 시스템 입력을 누락한 케이스로 보입니다."\n\n3. 대응\n안세희 컨설팅팀장 - "이관해서 새 시스템에서도 잘못된 상태로 남으면 안 되니, 이관 전에 정리하고 가야 합니다." 고객사와 협의해 수기 처리 이력을 확인, 정정하는 절차를 추가하기로 함.\n\n4. 여도경 컨설팅선임\n화면 개발은 예정대로 완료됐다고 보고, 이관 이슈와는 무관하게 진행 가능함을 확인.', '홍재현 - 정합성 오류 수정 2월 초까지.', NULL, '2025-01-17 09:00:00', '2025-01-17 09:00:00', NULL),
(89, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2025-02-14-89', '오픈 준비 점검', '2025-02-14', '고객사(동해저축은행 본사)', '오픈 전 최종 점검', '홍재현 컨설팅선임 - 정합성 오류 340건 전량 수정 완료 보고. 고객사 실무진과 함께 건별로 확인해 정정했다고 설명.\n\n권도영 컨설팅선임 - 화면 개발 전량 완료, 통합 테스트 결과 특이 이슈 없음.\n\n안세희 컨설팅팀장 - 최종 리허설 일정 및 오픈 일정 확정. "이번엔 정합성 문제까지 다 걸러낸 상태로 리허설하는 거라 결과가 깨끗할 것으로 봅니다."', '안세희 - 오픈 일정 최종 확정.', NULL, '2025-02-14 09:00:00', '2025-02-14 09:00:00', NULL),
(90, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), 'MTG-2025-03-20-90', '프로젝트 종료 보고', '2025-03-20', '고객사(동해저축은행 본사)', '최종 산출물 인도', '1. 오픈 결과\n안세희 컨설팅팀장 - 시스템 오픈 완료 보고. 최종 리허설에서 발견된 이슈 없이 예정대로 오픈 진행.\n\n2. 인수인계\n권도영 컨설팅선임 - 고객사 운영 담당자 대상 시스템 사용 교육 완료. 홍재현 컨설팅선임 - 데이터 이관 결과 검증 리포트 인도.\n\n3. 고객사 피드백\n안세희 - "고객사 쪽에서 특히 이관 데이터 정합성 문제를 미리 잡아준 부분에 대해 감사하다는 얘기를 많이 하셨습니다. 나중에 문제 됐으면 훨씬 골치 아팠을 거라고요."\n\n4. 후속 지원\n여도경 컨설팅선임이 오픈 후 1개월간 안정화 지원을 담당하기로 함.', '안정화 기간 지원.', NULL, '2025-03-20 09:00:00', '2025-03-20 09:00:00', NULL),
(91, 13, (SELECT id FROM users WHERE employee_no='DT22-0018'), 'MTG-2024-11-06-91', 'MTS 리뉴얼 1차 킥오프', '2024-11-06', '22F 포커스룸', '리뉴얼 범위 합의', '1. 배경\n다온증권 MTS(모바일트레이딩시스템)의 UI가 노후화됐다는 내부·고객 피드백이 누적됨에 따라 리뉴얼을 추진했다. 임다혜 FE팀장 - "화면마다 스타일이 조금씩 다르고, 컴포넌트도 화면별로 새로 만들어 쓰다 보니 일관성이 떨어진 지 오래됐습니다. 이번엔 디자인시스템부터 제대로 잡고 가려고 합니다."\n\n2. 진행 방향\n1차는 디자인시스템 기반 마련과 핵심 화면 8개 적용까지로 범위를 한정. 전체 화면 전수 적용은 이후 단계로 미루기로 함.\n\n3. 역할 분담\n최이안 선임 - 디자인시스템 컴포넌트 설계. 오하린 파트장 - 화면 적용 총괄. 남시우 파트장 - 우선순위 및 사용성 관점 자문.\n\n4. 일정\n디자인시스템 구축 → 컴포넌트 개발 → 화면 적용 → 사용성 테스트 → 오픈 순.', '설계 착수.', NULL, '2024-11-06 09:00:00', '2024-11-06 09:00:00', NULL),
(92, 13, (SELECT id FROM users WHERE employee_no='DT22-0145'), 'MTG-2024-11-27-92', '디자인시스템 방향 확정', '2024-11-27', '22F 포커스룸', '디자인 원칙 합의', '최이안 FE선임 - 디자인시스템 컴포넌트 목록 초안 제시. 버튼, 입력폼, 테이블, 차트 등 총 10종의 핵심 컴포넌트로 구성.\n\n최이안 - "지금까지 화면마다 따로 만들던 걸 이번에 다 통일하려고 합니다. 특히 차트 컴포넌트는 MTS 특성상 제일 많이 쓰이는 만큼 처음부터 신경 써서 설계하고 있습니다."\n\n남시우 FE파트장 - 화면별 적용 우선순위 제안. "거래 관련 화면(주문, 잔고 조회)을 먼저 적용해야 사용자 체감이 크다고 봅니다. 정보성 화면은 나중에 해도 괜찮을 것 같아요."\n\n우선순위 반영해 적용 순서 확정.', '최이안 - 핵심 컴포넌트 10종 12월 중 완성.', NULL, '2024-11-27 09:00:00', '2024-11-27 09:00:00', NULL),
(93, 13, (SELECT id FROM users WHERE employee_no='DT22-0145'), 'MTG-2024-12-18-93', '컴포넌트 개발 점검', '2024-12-18', '22F 포커스룸', '진행률 확인', '최이안 FE선임 - 핵심 컴포넌트 10종 중 7종 완성 보고. "버튼, 입력폼처럼 단순한 것들은 빨리 끝났는데, 차트 컴포넌트가 예상보다 손이 많이 갑니다. 여러 화면에서 쓰이다 보니 옵션을 유연하게 만들어야 해서요."\n\n오하린 FE파트장 - 완성된 7종을 기준으로 화면 적용에 착수했다고 보고. "먼저 나온 것부터 적용해보면서 컴포넌트 사용성도 같이 검증하고 있습니다."', '최이안 - 잔여 3종 1월 중 완성.', NULL, '2024-12-18 09:00:00', '2024-12-18 09:00:00', NULL),
(94, 13, (SELECT id FROM users WHERE employee_no='DT22-0143'), 'MTG-2025-01-22-94', '화면 적용 진행 점검', '2025-01-22', '22F 포커스룸', '적용 진행률 확인', '최이안 FE선임 - 핵심 컴포넌트 10종 전량 완성 보고.\n\n오하린 FE파트장 - 주요 화면 8개 중 4개(주문, 잔고 조회, 거래내역, 관심종목) 적용 완료. "우선순위대로 거래 관련 화면부터 먼저 끝냈습니다. 나머지 4개도 컴포넌트가 다 나온 상태라 속도는 붙을 것 같아요."', '오하린 - 잔여 화면 4개 2월 중 적용.', NULL, '2025-01-22 09:00:00', '2025-01-22 09:00:00', NULL),
(95, 13, (SELECT id FROM users WHERE employee_no='DT22-0018'), 'MTG-2025-03-05-95', '1차 개발 완료 점검', '2025-03-05', '22F 포커스룸', '개발 완료 확인', '오하린 FE파트장 - 주요 화면 8개 전체 적용 완료 보고. 예정보다 2주 늦었으나(2월 목표 → 3월 초), 전체 일정에는 큰 영향 없음.\n\n임다혜 FE팀장 - 개발 완료를 확인하고 사용성 테스트 일정을 4월로 확정. "디자인시스템 도입 목적 자체가 사용자 경험 개선이니, 실제 사용자 반응을 꼭 확인하고 넘어가야 합니다."\n\n최이안 FE선임 - 사용성 테스트 시나리오 작성을 맡기로 함.', '최이안 - 사용성 테스트 시나리오 작성.', NULL, '2025-03-05 09:00:00', '2025-03-05 09:00:00', NULL),
(96, 13, (SELECT id FROM users WHERE employee_no='DT22-0143'), 'MTG-2025-04-16-96', '사용성 테스트 진행 점검', '2025-04-16', '22F 포커스룸', '테스트 결과 중간 공유', '사용성 테스트 참가자 15명 중 10명 완료.\n\n최이안 FE선임 - 초기 반응 공유. "다들 화면이 확실히 정리된 느낌이라는 반응입니다. 특히 차트 화면 반응이 좋았어요. 다만 몇 분은 새 위치에 익숙해지는 데 시간이 좀 걸린다고 하셨습니다."\n\n오하린 FE파트장 - 익숙함 관련 코멘트는 리뉴얼에서 흔한 반응이라 크게 우려할 부분은 아니라고 판단, 나머지 5명 테스트를 이어가기로 함.', '오하린 - 나머지 5명 테스트 완료.', NULL, '2025-04-16 09:00:00', '2025-04-16 09:00:00', NULL),
(97, 13, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2025-06-20-97', '오픈 전 최종 점검', '2025-06-20', '22F 포커스룸', '오픈 준비 상태 확인', '남시우 FE파트장 진행.\n\n사용성 테스트 결과 종합 공유. 참가자 15명 전원 완료, 전반적으로 긍정 평가(만족도 4.2/5). 부정 응답은 주로 "새로운 위치 적응 기간"에 관한 것으로, 별도 기능 개선보다는 온보딩 안내로 대응하기로 함.\n\n남시우 - "테스트 결과가 나쁘지 않아서 예정대로 오픈 가는 걸로 보고 있습니다. 온보딩 툴팁 정도만 추가하면 될 것 같아요."\n\n임다혜 FE팀장 - 오픈 일정 확정 승인.', '오픈 일정 확정.', NULL, '2025-06-20 09:00:00', '2025-06-20 09:00:00', NULL),
(98, 13, (SELECT id FROM users WHERE employee_no='DT22-0018'), 'MTG-2025-06-30-98', '오픈 완료 보고', '2025-06-30', '22F 포커스룸', '프로젝트 종료 보고', '1. 오픈 결과\nMTS 리뉴얼 1차 정식 오픈 완료. 임다혜 FE팀장 - 오픈 직후 모니터링 결과 특이 이슈 없음 확인.\n\n2. 회고\n최이안 FE선임 - "디자인시스템을 처음 잡는 게 제일 오래 걸렸는데, 한번 만들어두니 이후 컴포넌트 조합이나 화면 적용은 확실히 빨라졌습니다."\n오하린 FE파트장 - 화면 적용 경험을 바탕으로 향후 확산 시 예상 소요 기간을 가늠할 수 있게 됐다고 언급.\n\n3. 다음 과제\n임다혜 - "이번에 만든 디자인시스템을 MTS 나머지 화면뿐 아니라 다른 서비스에도 확산하는 걸 다음 과제로 보고 있습니다." 최이안이 타 서비스 확산 계획을 수립하기로 함.', '최이안 - 타 서비스 확산 계획 수립.', NULL, '2025-06-30 09:00:00', '2025-06-30 09:00:00', NULL),
(99, 14, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'MTG-2025-01-08-99', 'FDS 엔진 v2 킥오프', '2025-01-08', '21F 포커스룸', '2세대 개발 목표 설정', '1. v1 한계 리뷰\n고은결 데이터팀장 - FDS 엔진 v1(룰 기반)의 한계를 정리해 공유. 신종 이상거래 패턴에 대응하려면 룰을 계속 추가해야 하는데, 룰이 늘어날수록 정상 거래까지 걸리는 경우(오탐)도 함께 늘어나는 구조적 문제가 있다고 설명.\n\n2. v2 방향\n"이번엔 룰 기반에서 벗어나서 머신러닝 기반 탐지 모델을 도입해보려고 합니다. 패턴을 사람이 일일이 룰로 짜는 게 아니라 데이터에서 학습하게 하는 거죠." 목표는 오탐률 개선.\n\n3. 참석자 의견\n백서윤 데이터파트장 - "머신러닝 도입은 처음이라 신중하게 접근해야 할 것 같습니다. 모델 후보군부터 비교 검토하고 시작하시죠."\n오채린 사업기획파트장 - "이 사업이 지금까지 적자였던 만큼, 이번 시도가 성과로 이어지는지는 사업본부에서도 계속 지켜볼 겁니다."\n\n4. 역할 분담\n백서윤 - 모델 설계 총괄. 마예린 - 데이터 및 튜닝 지원.', '모델 설계 착수.', NULL, '2025-01-08 09:00:00', '2025-01-08 09:00:00', NULL),
(100, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2025-02-12-100', '모델 설계 진행 점검', '2025-02-12', '21F 포커스룸', '설계 진행 확인', '백서윤 데이터파트장 - 머신러닝 모델 후보 3종(로지스틱 회귀, 랜덤포레스트, SVM) 비교 결과 공유.\n\n- 로지스틱 회귀: 해석 용이, 성능 개선폭 작음\n- 랜덤포레스트: 성능 개선폭 크고 속도도 준수\n- SVM: 성능은 나쁘지 않으나 대용량 데이터에서 학습 속도 저하\n\n백서윤 - "지금 저희 데이터 규모를 감안하면 랜덤포레스트가 성능·속도 균형이 제일 좋아 보입니다. 다만 최종 결정 전에 실제 데이터로 한 번 더 검증해보고 싶습니다."', '백서윤 - 최적 모델 선정 3월 초까지.', NULL, '2025-02-12 09:00:00', '2025-02-12 09:00:00', NULL),
(101, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2025-03-19-101', '모델 선정 완료 보고', '2025-03-19', '21F 포커스룸', '모델 확정', '백서윤 데이터파트장 - 랜덤포레스트 기반 모델 최종 선정 보고. 실제 데이터 검증에서도 세 후보 중 가장 안정적인 결과를 보였다고 설명.\n\n마예린 데이터선임 - 학습 데이터셋 구축을 맡기로 함. "이상 거래 라벨링된 데이터가 충분치 않아서, 과거 신고 이력이랑 수기 처리 이력까지 다 모아서 데이터셋을 만들어야 할 것 같습니다."', '마예린 - 학습 데이터셋 구축.', NULL, '2025-03-19 09:00:00', '2025-03-19 09:00:00', NULL),
(102, 14, (SELECT id FROM users WHERE employee_no='DT24-0040'), 'MTG-2025-04-23-102', '학습 데이터 준비 점검', '2025-04-23', '21F 포커스룸', '데이터 준비 확인', '마예린 데이터선임 - 학습 데이터셋 구축 완료 보고. 과거 2년치 거래 데이터와 이상거래 신고·처리 이력을 결합해 라벨링된 학습셋 구성.\n\n초기 학습 결과\n랜덤포레스트 모델 초기 학습 결과 오탐률 v1 대비 15% 개선 확인. 마예린 - "일단 첫 학습부터 15% 개선이면 나쁘지 않은 시작입니다. 하이퍼파라미터 튜닝하면 더 나아질 여지가 있어 보여요."', '마예린 - 정밀 튜닝 착수.', NULL, '2025-04-23 09:00:00', '2025-04-23 09:00:00', NULL),
(103, 14, (SELECT id FROM users WHERE employee_no='DT24-0040'), 'MTG-2025-06-04-103', '모델 튜닝 중간 점검', '2025-06-04', '21F 포커스룸', '튜닝 진행 확인', '마예린 데이터선임 - 정밀 튜닝 결과 오탐률 22% 개선 달성 보고. "피처를 좀 더 추가하고 하이퍼파라미터도 여러 조합으로 실험해봤는데, 22%까지는 나왔습니다."\n\n백서윤 데이터파트장 - 성과가 가시화되고 있는 만큼, 이 시점에서 사업성 논의를 병행할 필요가 있다고 제기. "기술적으로는 확실히 좋아지고 있는데, 이게 사업 존속 논의랑 맞물려 있는 사업이라 미리 공유해두는 게 나을 것 같습니다."\n\n오채린 사업기획파트장에게 사업성 검토 회의 소집을 요청하기로 함.', '오채린 - 손익 시나리오 작성.', NULL, '2025-06-04 09:00:00', '2025-06-04 09:00:00', NULL),
(104, 14, (SELECT id FROM users WHERE employee_no='DT22-0082'), 'MTG-2025-07-09-104', '사업성 검토 회의', '2025-07-09', '22F 대회의실', '사업본부 의견 수렴', '1. 배경\nFDS 엔진 사업의 누적 적자 상황에서, v2 개발 성과를 바탕으로 사업본부 의견을 수렴하기 위한 자리.\n\n2. 최재훈 사업기획선임 발표\n오탐률 22% 개선 결과를 바탕으로 손익 시나리오를 발표. "직접적인 매출은 없는 사업이지만, 이상거래 탐지로 방지되는 손실 금액을 추산하면 상당한 리스크 관리 가치가 있습니다. 다만 이걸 회계상 매출로 잡을 수는 없어서, 손익 개선으로 바로 보이진 않습니다."\n\n3. 논의\n오채린 사업기획파트장 - "적자는 여전하지만, 리스크 관리 가치는 인정할 만합니다. 다만 이게 언제까지 이런 식으로 갈 수 있을지는 계속 지켜봐야 할 것 같아요."\n\n고은결 데이터팀장 - "기술적으로는 계속 개선되고 있다는 걸 숫자로 보여드릴 수 있습니다. 회수 시점에 대한 명확한 답은 저희도 지금은 드리기 어렵습니다."\n\n4. 결론\n적자는 지속되나 리스크 관리 가치를 인정받아 프로젝트는 예정대로 진행. 고은결이 이번 논의 결과를 경영회의에 보고하기로 함.', '고은결 - 경영회의 보고.', NULL, '2025-07-09 09:00:00', '2025-07-09 09:00:00', NULL),
(105, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2025-08-13-105', '백엔드 연동 점검', '2025-08-13', '21F 포커스룸', '연동 진행 확인', '백서윤 데이터파트장 - 사업성 검토 결과 프로젝트 지속 확정에 따라 백엔드 연동 개발 착수 보고.\n\n실시간 처리 설계가 진행 중이며, 거래 발생 시점에 모델 추론 결과를 즉시 반영하는 구조로 설계하고 있다고 설명. "v1도 실시간이긴 했지만 룰 기반이라 단순했는데, 모델 추론이 들어가면서 구조가 좀 더 복잡해졌습니다. 성능 확보가 관건입니다."', '백서윤 - 연동 진행률 격주 보고.', NULL, '2025-08-13 09:00:00', '2025-08-13 09:00:00', NULL),
(106, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), 'MTG-2025-09-24-106', '연동 중간 점검', '2025-09-24', '21F 포커스룸', '진행률 확인', '백서윤 데이터파트장 - 백엔드 연동 70% 완료 보고. 실시간 처리 목표치에 근접한 상태.\n\n백서윤 - "초기 우려했던 것보다는 성능이 잘 나오고 있습니다. 남은 30%는 예외 케이스 처리랑 안정성 검증 위주라 큰 변수는 없어 보입니다."\n\n마예린 데이터선임 - 모델 자체는 안정적으로 동작 중이며, 운영 데이터가 쌓이는 대로 재학습 주기도 검토해보겠다고 언급.', '백서윤 - 연동 완료 10월 말까지.', NULL, '2025-09-24 09:00:00', '2025-09-24 09:00:00', NULL),
(107, 14, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'MTG-2025-11-15-107', '최종 점검 회의', '2025-11-15', '21F 포커스룸', '프로젝트 종료 준비', '백서윤 데이터파트장 - 백엔드 연동 완료 및 최종 검증 결과 공유. 탐지 정확도 개선 결과를 종합 리뷰.\n\n최종 오탐률 개선폭은 20%(연동 과정에서 일부 재조정), 실시간 처리 성능도 목표치 충족.\n\n고은결 데이터팀장 - "v1 대비 확실히 나아졌습니다. 다만 이 정도로 만족할 수준인지는 계속 고민이 필요할 것 같아요. 결국 오탐이 여전히 남아있으니까요." 향후 추가 개선(v3) 필요성을 조심스럽게 언급.', 'v3 필요성 논의 시작.', NULL, '2025-11-15 09:00:00', '2025-11-15 09:00:00', NULL),
(108, 14, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'MTG-2025-12-31-108', '오픈 완료 보고', '2025-12-31', '21F 포커스룸', '프로젝트 종료 보고', '1. 오픈 결과\nFDS 엔진 v2 정식 오픈 완료. 백서윤 데이터파트장 - 오픈 후 2주간 모니터링 결과 특이 이슈 없음, 오탐률 개선 효과도 실제 운영 데이터에서 확인됐다고 보고.\n\n2. 회고\n마예린 데이터선임 - "머신러닝을 처음 도입하는 프로젝트라 걱정도 있었는데, 결과적으로는 확실한 개선을 만들었다고 생각합니다."\n\n3. v3 논의\n고은결 데이터팀장 - v3 필요성을 공식 의제로 제안. "v2로 룰 기반의 한계는 넘었지만, 지금 방식도 결국 오탐이 완전히 없어지는 건 아닙니다. 다음 단계로 더 정교한 모델이나 실시간 서빙 구조까지 고민해볼 시점이라고 봅니다." 다만 이 시점에서 v3 착수를 확정한 것은 아니고, 별도 기획안을 통해 검토하기로 함.', '고은결 - v3 기획안 2026년 1분기 작성.', NULL, '2025-12-31 09:00:00', '2025-12-31 09:00:00', NULL),
(109, 15, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'MTG-2024-11-15-109', '장애 긴급 대응 회의', '2024-11-15', '21F 관제센터', '이체 지연 장애 초기 대응', '1. 장애 현황\n오전 10시 12분경부터 다온뱅크 이체 서비스에서 지연 발생. 평소 평균 1.2초이던 이체 처리 시간이 15초 이상으로 증가, 일부 건은 타임아웃 발생. 진병호 인프라팀장이 관제 알림을 확인하고 즉시 소집.\n\n2. 초기 파악\n서인호 인프라파트장 - "네트워크 구간 모니터링 상으로는 이상 없습니다. 코어뱅킹 연동 쪽 응답이 느려지는 게 보이는데, 저희 쪽 문제인지 코어뱅킹 쪽 문제인지는 아직 확인 중입니다."\n\n황시온 DevOps선임 - 서버 리소스(CPU, 메모리) 사용률은 평소 대비 특이사항 없음을 확인. "리소스 문제는 아닌 것 같고, 특정 연동 구간에서 병목이 있는 것 같습니다."\n\n3. 당직자 역할 분담\n진병호 - 상황 총괄 및 경영진 보고. 서인호 - 네트워크·연동 구간 조사. 황시온 - 서버·인프라 리소스 모니터링. 지동원 - 코어뱅킹팀과 협의 채널 개설. 방윤아·하도경 - 로그 수집 및 초기 데이터 정리.\n\n4. 임시 조치\n이체 요청 큐잉 방식으로 일시 전환해 타임아웃으로 인한 완전 실패는 방지, 처리 지연은 계속되는 상태로 원인 분석 병행.\n\n5. 고객 영향\n오전 10시12분~11시05분(약 53분) 동안 이체 처리 지연, 완전 실패 건은 없었으나 대기 시간 급증으로 고객 문의 다수 접수. 11시 05분경 원인 조치 후 정상화.\n\n6. 원인(추정)\n코어뱅킹 측 야간 배치 작업이 예정보다 길어져 이체 연동 구간과 리소스를 일부 공유하며 병목 발생한 것으로 잠정 파악. 코어뱅킹팀 확인 요청.', '원인 분석 즉시 착수.', NULL, '2024-11-15 09:00:00', '2024-11-15 09:00:00', NULL),
(110, 15, (SELECT id FROM users WHERE employee_no='DT22-0058'), 'MTG-2024-11-20-110', '포스트모템', '2024-11-20', '21F 대회의실', '장애 회고 및 재발 방지', '1. 원인 확정\n지동원 인프라파트장 - 코어뱅킹팀과 협의 결과 공유. 전날 배치 작업 스케줄 변경으로 야간 배치가 오전 10시까지 연장 실행됐고, 이 시간대에 이체 연동 구간의 DB 커넥션 풀을 배치 작업과 실거래 처리가 함께 점유하면서 병목이 발생한 것으로 확인.\n\n2. 원칙 확인\n진병호 인프라팀장 - "오늘은 원인 파악과 재발 방지에 집중하고, 특정 개인의 책임을 묻는 자리가 아닙니다." 사실 위주로 타임라인을 재구성해 리뷰.\n\n3. 타임라인 리뷰\n- 09:47 코어뱅킹 배치 스케줄 변경 반영(사전 공지 누락)\n- 10:12 이체 지연 최초 감지\n- 10:15 긴급 대응팀 소집\n- 10:35 임시 조치(큐잉 전환) 적용\n- 11:05 코어뱅킹 배치 종료, 서비스 정상화\n\n4. 재발 방지 방안\n서인호 인프라파트장 - "가장 큰 문제는 배치 스케줄 변경이 저희 쪽에 사전 공지되지 않았다는 점입니다. 코어뱅킹팀과 스케줄 변경 시 상호 통보 프로세스를 만들어야 합니다."\n\n황시온 DevOps선임 - 이체 연동 구간과 배치 작업의 DB 커넥션 풀을 물리적으로 분리하는 방안 제안. "공유 풀을 쓰는 구조 자체가 근본 원인이니, 분리하면 이런 유형의 문제는 재발하지 않을 겁니다."\n\n5. 온콜 체계 점검\n방윤아 인프라선임 - 이번 대응에서 당직자 소집까지 3분이 걸렸는데, 알림 확인 후 대응 매뉴얼을 찾는 데 시간이 걸렸다고 지적. "매뉴얼이 있긴 한데 어디 있는지 헷갈렸습니다. 온콜 체계 자체를 다시 정리할 필요가 있어 보입니다."\n\n6. 액션 아이템\n- 코어뱅킹팀과 배치 스케줄 상호 통보 프로세스 수립\n- DB 커넥션 풀 분리\n- 온콜 대응 매뉴얼 정비 및 접근성 개선', '온콜 체계 개선안 수립.', NULL, '2024-11-20 09:00:00', '2024-11-20 09:00:00', NULL),
(111, 16, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'MTG-2024-04-01-111', '레거시 API 정리 킥오프', '2024-04-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '임동혁 BE선임 - 이전 시스템에서 넘어온 API 중 문서화가 안 된 것들을 전수 조사한 결과 공유. "얼마나 되는지 세어보니 87개인데, 이 중 절반 가까이가 지금도 쓰이는지조차 확실치 않습니다." 사용 로그를 기준으로 저사용 API를 먼저 골라내고, 남는 API는 문서화를 완료하는 것으로 목표 합의.', '세부 일정 수립.', NULL, '2024-04-01 09:00:00', '2024-04-01 09:00:00', NULL),
(112, 16, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'MTG-2024-08-15-112', '레거시 API 정리 종료 보고', '2024-08-15', '22F 포커스룸', '결과 점검 및 종료 보고', '임동혁 BE선임 - 87개 중 34개는 실제 미사용으로 확인돼 폐기, 나머지 53개는 문서화 완료. "폐기 전에 혹시 몰라서 한 달 동안 로그 모니터링을 했는데, 진짜 아무도 안 쓰더라고요." 유지보수 대상이 명확해져 향후 신규 개발자 온보딩에도 도움이 될 것으로 평가.', '산출물 정리 및 공유.', NULL, '2024-08-15 09:00:00', '2024-08-15 09:00:00', NULL),
(113, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), 'MTG-2024-05-01-113', '배치 작업 모니터링 고도화 킥오프', '2024-05-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '배서현 BE선임 - "배치가 새벽에 실패해도 담당자가 출근해서야 아는 경우가 많았습니다. 그사이 후속 작업까지 줄줄이 밀리고요." 실패 즉시 슬랙 알림이 가도록 모니터링 체계를 개선하는 것을 목표로 합의.', '세부 일정 수립.', NULL, '2024-05-01 09:00:00', '2024-05-01 09:00:00', NULL),
(114, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), 'MTG-2024-09-10-114', '배치 작업 모니터링 고도화 종료 보고', '2024-09-10', '22F 포커스룸', '결과 점검 및 종료 보고', '배서현 BE선임 - 실패 감지부터 알림까지 소요 시간을 기존 수 시간에서 3분 이내로 단축. "이제 새벽에 실패해도 당직자가 바로 확인할 수 있습니다. 체감이 확실히 다릅니다." 핵심 배치 22개에 우선 적용, 나머지는 순차 확대 예정.', '산출물 정리 및 공유.', NULL, '2024-09-10 09:00:00', '2024-09-10 09:00:00', NULL),
(115, 18, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2024-06-01-115', '인증 토큰 정책 개선 킥오프', '2024-06-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '하유진 BE파트장 - "서비스마다 토큰 만료 시간이 달라서, 어떤 건 30분마다 재로그인해야 하고 어떤 건 하루 종일 유지되고 그럽니다. 사용자 입장에서는 왜 이러는지 이해가 안 될 겁니다." 만료 정책을 통일하고 갱신 로직을 개선하는 것으로 목표 합의.', '세부 일정 수립.', NULL, '2024-06-01 09:00:00', '2024-06-01 09:00:00', NULL),
(116, 18, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2024-10-15-116', '인증 토큰 정책 개선 종료 보고', '2024-10-15', '22F 포커스룸', '결과 점검 및 종료 보고', '하유진 BE파트장 - 전 서비스 토큰 만료 정책을 액세스 30분/리프레시 2주로 통일, 자동 갱신 로직 적용 완료. "통일하고 나니 문의도 줄고 코드도 단순해졌습니다." 성공적으로 목표 달성.', '산출물 정리 및 공유.', NULL, '2024-10-15 09:00:00', '2024-10-15 09:00:00', NULL),
(117, 19, (SELECT id FROM users WHERE employee_no='DT22-0196'), 'MTG-2024-08-01-117', '그룹 채널 연동 안정화 킥오프', '2024-08-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '정예린 BE선임 - "외부 채널 연동이 한 달에 두세 번은 끊깁니다. 재시도 로직이 있긴 한데 감지 자체가 늦어서 사용자가 먼저 알아채는 경우가 많아요." 재시도 로직과 장애 감지를 보강하는 것이 목표.', '세부 일정 수립.', NULL, '2024-08-01 09:00:00', '2024-08-01 09:00:00', NULL),
(118, 19, (SELECT id FROM users WHERE employee_no='DT22-0196'), 'MTG-2025-01-20-118', '그룹 채널 연동 안정화 종료 보고', '2025-01-20', '22F 포커스룸', '결과 점검 및 종료 보고', '정예린 BE선임 - 장애 감지 시간을 단축하고 재시도 로직에 지수 백오프를 적용, 연동 끊김 발생 시에도 자동 복구되는 비율이 크게 늘었다고 보고. "이제 사용자가 먼저 알아채는 일은 거의 없어졌습니다." 목표 달성 확인.', '산출물 정리 및 공유.', NULL, '2025-01-20 09:00:00', '2025-01-20 09:00:00', NULL),
(119, 20, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2024-09-01-119', '코드 리뷰 프로세스 개선 TF 킥오프', '2024-09-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '하유진 BE파트장 - "파트마다 리뷰 기준이 달라서, A파트에서는 걸릴 게 B파트에서는 그냥 넘어가고 그럽니다. 품질 편차가 여기서 오는 것 같아요." 공통 체크리스트를 만들어 리뷰 품질을 표준화하는 것이 목표.', '세부 일정 수립.', NULL, '2024-09-01 09:00:00', '2024-09-01 09:00:00', NULL),
(120, 20, (SELECT id FROM users WHERE employee_no='DT22-0190'), 'MTG-2024-11-10-120', '코드 리뷰 프로세스 개선 TF 종료 보고', '2024-11-10', '22F 포커스룸', '결과 점검 및 종료 보고', '하유진 BE파트장 - 공통 체크리스트(보안·성능·테스트 커버리지 등 12개 항목) 제작 완료, 전 파트 시범 적용 결과 리뷰 소요 시간은 다소 늘었으나 반려율은 감소. "당장은 좀 번거로워해도, 결국 재작업이 줄어드는 방향이라 계속 가져가기로 했습니다."', '산출물 정리 및 공유.', NULL, '2024-11-10 09:00:00', '2024-11-10 09:00:00', NULL),
(121, 21, (SELECT id FROM users WHERE employee_no='DT22-0166'), 'MTG-2025-01-06-121', '결제 시스템 성능 개선 킥오프', '2025-01-06', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '배소현 BE선임 - "트래픽 몰릴 때마다 결제 처리 지연 문의가 들어옵니다. 원인은 대충 짐작은 가는데 정확히 병목이 어딘지는 프로파일링을 해봐야 할 것 같습니다." 병목 구간을 찾아 응답 시간을 단축하는 것이 목표.', '세부 일정 수립.', NULL, '2025-01-06 09:00:00', '2025-01-06 09:00:00', NULL),
(122, 21, (SELECT id FROM users WHERE employee_no='DT22-0166'), 'MTG-2025-05-20-122', '결제 시스템 성능 개선 종료 보고', '2025-05-20', '22F 포커스룸', '결과 점검 및 종료 보고', '배소현 BE선임 - 프로파일링 결과 결제 승인 API의 동기 외부 호출이 병목으로 확인, 비동기 처리로 전환해 트래픽 몰릴 때 응답 시간을 평균 60% 단축. "가장 큰 원인 하나만 잡았는데도 효과가 확실했습니다."', '산출물 정리 및 공유.', NULL, '2025-05-20 09:00:00', '2025-05-20 09:00:00', NULL),
(123, 22, (SELECT id FROM users WHERE employee_no='DT22-0019'), 'MTG-2025-02-03-123', 'DB 인덱스 정비 킥오프', '2025-02-03', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '서강우 BE팀장 - "서비스가 커지면서 예전엔 안 걸리던 쿼리들이 이제 몇 초씩 걸립니다. 인덱스를 그때그때 땜질식으로 추가해온 게 누적된 결과인 것 같아요." 전면 재설계 필요성에 합의.', '세부 일정 수립.', NULL, '2025-02-03 09:00:00', '2025-02-03 09:00:00', NULL),
(124, 22, (SELECT id FROM users WHERE employee_no='DT22-0019'), 'MTG-2025-04-15-124', 'DB 인덱스 정비 종료 보고', '2025-04-15', '22F 포커스룸', '결과 점검 및 종료 보고', '서강우 BE팀장 - 핵심 테이블 18개 인덱스 재설계 완료, 느린 쿼리(1초 이상) 비중이 기존 대비 크게 감소. "인덱스 하나 잘못 걸려 있으면 전체가 밀리는 거라, 이번엔 실행계획까지 다 확인하고 갔습니다."', '산출물 정리 및 공유.', NULL, '2025-04-15 09:00:00', '2025-04-15 09:00:00', NULL),
(125, 23, (SELECT id FROM users WHERE employee_no='DT22-0186'), 'MTG-2025-05-01-125', '그룹 인증 로그 표준화 킥오프', '2025-05-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '임도현 BE선임 - "감사 시즌마다 시스템별로 로그 포맷이 달라서 집계하는 데만 며칠씩 걸립니다. 이번엔 아예 포맷을 통일해버리려고 합니다." 로그 포맷 통일로 감사 대응 효율을 높이는 것이 목표.', '세부 일정 수립.', NULL, '2025-05-01 09:00:00', '2025-05-01 09:00:00', NULL),
(126, 23, (SELECT id FROM users WHERE employee_no='DT22-0186'), 'MTG-2025-08-15-126', '그룹 인증 로그 표준화 종료 보고', '2025-08-15', '22F 포커스룸', '결과 점검 및 종료 보고', '임도현 BE선임 - 표준 로그 포맷(JSON 스키마) 정의 및 전 인증 시스템 적용 완료. "다음 감사 때부터는 집계 스크립트 하나로 다 뽑을 수 있을 겁니다." 목표 달성.', '산출물 정리 및 공유.', NULL, '2025-08-15 09:00:00', '2025-08-15 09:00:00', NULL),
(127, 24, (SELECT id FROM users WHERE employee_no='DT22-0198'), 'MTG-2025-06-02-127', 'API 게이트웨이 1차 구축 킥오프', '2025-06-02', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '조태현 BE파트장 - "서비스별로 API를 각자 관리하다 보니 트래픽 급증 상황에서 전체를 통제할 방법이 없었습니다. 게이트웨이를 두면 레이트리밋이나 인증을 한곳에서 처리할 수 있습니다." 게이트웨이 도입으로 트래픽 일원화가 목표.', '세부 일정 수립.', NULL, '2025-06-02 09:00:00', '2025-06-02 09:00:00', NULL),
(128, 24, (SELECT id FROM users WHERE employee_no='DT22-0198'), 'MTG-2025-11-14-128', 'API 게이트웨이 1차 구축 종료 보고', '2025-11-14', '22F 포커스룸', '결과 점검 및 종료 보고', '조태현 BE파트장 - 핵심 서비스 6개를 게이트웨이 뒤로 이전, 레이트리밋·인증 중앙화 완료. "1차는 핵심 서비스만 넣었고, 나머지는 다음 단계에서 순차적으로 옮길 계획입니다."', '산출물 정리 및 공유.', NULL, '2025-11-14 09:00:00', '2025-11-14 09:00:00', NULL),
(129, 25, (SELECT id FROM users WHERE employee_no='DT22-0164'), 'MTG-2025-09-01-129', '코어뱅킹 배치 리팩토링 킥오프', '2025-09-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '윤성우 BE선임 - "코드가 워낙 오래돼서 신규 입사자가 붙으면 손도 못 대고 도망갑니다. 주석도 없고 변수명도 알아보기 힘들고요." 구조를 정리해 유지보수성을 높이는 것이 목표.', '세부 일정 수립.', NULL, '2025-09-01 09:00:00', '2025-09-01 09:00:00', NULL),
(130, 25, (SELECT id FROM users WHERE employee_no='DT22-0164'), 'MTG-2026-01-20-130', '코어뱅킹 배치 리팩토링 종료 보고', '2026-01-20', '22F 포커스룸', '결과 점검 및 종료 보고', '윤성우 BE선임 - 핵심 배치 잡 15개 구조 정리 및 문서화 완료, 기능 변경 없이 가독성만 개선. "이제 새로 들어온 분도 코드 보고 대충 흐름은 따라갈 수 있을 겁니다."', '산출물 정리 및 공유.', NULL, '2026-01-20 09:00:00', '2026-01-20 09:00:00', NULL),
(131, 26, (SELECT id FROM users WHERE employee_no='DT22-0201'), 'MTG-2026-01-05-131', '장애 대응 매뉴얼 정비 킥오프', '2026-01-05', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '임소현 BE선임 - "장애 대응이 결국 경험 많은 몇 명한테 쏠려 있습니다. 그분들이 자리를 비우면 신입은 뭐부터 해야 할지 모릅니다." 표준 매뉴얼을 만들어 대응 속도를 높이는 것이 목표.', '세부 일정 수립.', NULL, '2026-01-05 09:00:00', '2026-01-05 09:00:00', NULL),
(132, 26, (SELECT id FROM users WHERE employee_no='DT22-0201'), 'MTG-2026-03-10-132', '장애 대응 매뉴얼 정비 종료 보고', '2026-03-10', '22F 포커스룸', '결과 점검 및 종료 보고', '임소현 BE선임 - 장애 유형별(DB, 네트워크, 외부연동 등) 대응 매뉴얼 8종 작성 완료, 신규 입사자 대상 모의 훈련도 함께 진행. "실제로 훈련해보니 매뉴얼에서 빠진 부분도 몇 개 발견해서 같이 보완했습니다."', '산출물 정리 및 공유.', NULL, '2026-03-10 09:00:00', '2026-03-10 09:00:00', NULL),
(133, 27, (SELECT id FROM users WHERE employee_no='DT22-0188'), 'MTG-2025-03-03-133', '테스트 커버리지 확대 TF 킥오프', '2025-03-03', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '곽하늘 BE사원 - "핵심 결제·정산 모듈 커버리지가 40%도 안 됩니다. 배포할 때마다 다들 불안해하는 게 이해가 갑니다." 우선순위 높은 모듈부터 테스트를 추가하는 것이 목표.', '세부 일정 수립.', NULL, '2025-03-03 09:00:00', '2025-03-03 09:00:00', NULL),
(134, 27, (SELECT id FROM users WHERE employee_no='DT22-0188'), 'MTG-2025-06-01-134', '테스트 커버리지 확대 TF 중단 보고', '2025-06-01', '22F 포커스룸', '결과 점검 및 중단 보고', '곽하늘 BE사원 - 결제 모듈 커버리지를 40%에서 58%까지 올린 상태에서 중단. "다온뱅크 여신고도화 쪽으로 인력이 급하게 재배치되면서, 계획했던 나머지 모듈은 손을 못 댔습니다. 지금까지 작업한 테스트 코드는 남겨뒀으니 나중에 재개할 수 있을 겁니다."', '산출물 정리 및 공유.', NULL, '2025-06-01 09:00:00', '2025-06-01 09:00:00', NULL),
(135, 28, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2024-01-15-135', '컴포넌트 라이브러리 v1 구축 킥오프', '2024-01-15', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '남시우 FE파트장 - "화면마다 버튼 색이랑 인풋 스타일이 조금씩 달라요. 디자이너가 하나씩 다시 지적해줘야 하는 상황이라, 아예 공통 컴포넌트를 만들어서 그럴 일 자체를 없애려고 합니다." 공통 컴포넌트로 개발 속도와 디자인 일관성을 높이는 것이 목표.', '세부 일정 수립.', NULL, '2024-01-15 09:00:00', '2024-01-15 09:00:00', NULL),
(136, 28, (SELECT id FROM users WHERE employee_no='DT22-0142'), 'MTG-2024-04-20-136', '컴포넌트 라이브러리 v1 구축 종료 보고', '2024-04-20', '22F 포커스룸', '결과 점검 및 종료 보고', '남시우 FE파트장 - 버튼·인풋·모달 등 핵심 컴포넌트 15종 완성. "일단 자주 쓰는 것부터 만들었고, 다음 화면 작업부터는 이걸로 조립하듯 가져다 쓰면 됩니다." 목표 달성 확인.', '산출물 정리 및 공유.', NULL, '2024-04-20 09:00:00', '2024-04-20 09:00:00', NULL),
(137, 29, (SELECT id FROM users WHERE employee_no='DT22-0145'), 'MTG-2024-05-01-137', '모바일 반응형 개선 킥오프', '2024-05-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '최이안 FE선임 - "모바일 브라우저로 들어오면 표가 화면 밖으로 삐져나가거나 버튼이 겹치는 화면이 꽤 있습니다. PC 기준으로만 만들어온 티가 나요." 반응형 대응을 정비해 모바일 사용성을 높이는 것이 목표.', '세부 일정 수립.', NULL, '2024-05-01 09:00:00', '2024-05-01 09:00:00', NULL),
(138, 29, (SELECT id FROM users WHERE employee_no='DT22-0145'), 'MTG-2024-08-15-138', '모바일 반응형 개선 종료 보고', '2024-08-15', '22F 포커스룸', '결과 점검 및 종료 보고', '최이안 FE선임 - 주요 화면 20개 반응형 적용 완료. "레이아웃 깨짐은 다 잡았고, 남은 건 모바일에서 클릭 영역이 좀 작다는 피드백인데 이건 다음 과제로 넘기겠습니다."', '산출물 정리 및 공유.', NULL, '2024-08-15 09:00:00', '2024-08-15 09:00:00', NULL),
(139, 30, (SELECT id FROM users WHERE employee_no='DT22-0018'), 'MTG-2024-09-02-139', '접근성(a11y) 1차 개선 킥오프', '2024-09-02', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '임다혜 FE팀장 - "스크린리더로 점검해보니 이미지 대체 텍스트도 없고, 키보드만으로는 못 들어가는 메뉴도 있었습니다. 주요 화면부터 기준을 맞춰야 합니다." 주요 화면 접근성 기준 충족이 목표.', '세부 일정 수립.', NULL, '2024-09-02 09:00:00', '2024-09-02 09:00:00', NULL),
(140, 30, (SELECT id FROM users WHERE employee_no='DT22-0018'), 'MTG-2024-12-13-140', '접근성(a11y) 1차 개선 종료 보고', '2024-12-13', '22F 포커스룸', '결과 점검 및 종료 보고', '임다혜 FE팀장 - 주요 화면 12개 대상 WCAG 기준 충족 완료. "1차는 제일 많이 쓰는 화면 위주로 했고, 나머지는 감사 지적 사항 보면서 2차로 이어가려고 합니다."', '산출물 정리 및 공유.', NULL, '2024-12-13 09:00:00', '2024-12-13 09:00:00', NULL),
(141, 31, (SELECT id FROM users WHERE employee_no='DT22-0155'), 'MTG-2025-01-06-141', '번들 사이즈 최적화 킥오프', '2025-01-06', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '곽민서 FE선임 - "초기 로딩할 때 안 쓰는 라이브러리까지 다 같이 불러오고 있었습니다. 번들 분석 도구로 찍어보니 생각보다 덩치 큰 게 많더라고요." 불필요한 의존성을 정리해 번들 크기를 줄이는 것이 목표.', '세부 일정 수립.', NULL, '2025-01-06 09:00:00', '2025-01-06 09:00:00', NULL),
(142, 31, (SELECT id FROM users WHERE employee_no='DT22-0155'), 'MTG-2025-03-14-142', '번들 사이즈 최적화 종료 보고', '2025-03-14', '22F 포커스룸', '결과 점검 및 종료 보고', '곽민서 FE선임 - 코드 스플리팅과 미사용 의존성 제거로 초기 번들 사이즈를 절반 가까이 줄임. "체감상 초기 로딩이 확실히 빨라졌다는 얘기를 들었습니다."', '산출물 정리 및 공유.', NULL, '2025-03-14 09:00:00', '2025-03-14 09:00:00', NULL),
(143, 32, (SELECT id FROM users WHERE employee_no='DT22-0144'), 'MTG-2025-04-01-143', '다크모드 지원 킥오프', '2025-04-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '배준호 FE파트장 - "야간 근무하는 분들이 화면이 너무 밝아서 눈 아프다는 얘기를 종종 하시더라고요. 사내 시스템에 다크모드가 없다는 게 계속 걸렸습니다." 전 화면 다크모드 지원이 목표.', '세부 일정 수립.', NULL, '2025-04-01 09:00:00', '2025-04-01 09:00:00', NULL),
