(150, 36, (SELECT id FROM users WHERE employee_no='DT22-0127'), 'MTG-2024-04-01-150', '테스트 자동화 도입 TF 킥오프', '2024-04-01', '22F 포커스룸', '착수 배경 공유 및 목표 합의', '문가온 QA파트장 - "회귀 테스트를 릴리즈마다 사람이 손으로 다 돌리고 있습니다. 릴리즈 하나에 이틀씩 걸리는데, 정작 새로 짠 기능 테스트할 시간은 줄어드는 구조예요." 핵심 시나리오부터 자동화해 릴리즈 속도를 높이는 것이 목표.', '세부 일정 수립.', NULL, '2024-04-01 09:00:00', '2024-04-01 09:00:00', NULL),
(151, 36, (SELECT id FROM users WHERE employee_no='DT22-0127'), 'MTG-2024-07-12-151', '테스트 자동화 도입 TF 종료 보고', '2024-07-12', '22F 포커스룸', '결과 점검 및 종료 보고', '문가온 QA파트장 - 핵심 시나리오 40건 자동화 완료, 회귀 테스트 소요 시간을 이틀에서 반나절로 단축. "완전 자동화는 아니지만, 사람이 봐야 할 부분에 집중할 시간이 생긴 게 제일 큽니다."', '산출물 정리 및 공유.', NULL, '2024-07-12 09:00:00', '2024-07-12 09:00:00', NULL),
