(153, 37, (SELECT id FROM users WHERE employee_no='DT22-0020'), 'MTG-2024-10-11-153', '버그 트래킹 프로세스 정비 종료 보고', '2024-10-11', '22F 포커스룸', '결과 점검 및 종료 보고', '정미르 QA팀장 - 표준 버그 리포트 템플릿(재현 조건·환경·기대 결과 필수 항목) 도입 완료. "재현이 안 돼서 반려되는 케이스가 눈에 띄게 줄었습니다."', '산출물 정리 및 공유.', NULL, '2024-10-11 09:00:00', '2024-10-11 09:00:00', NULL),
